// Chartolj! — English lesson translations, module 2 (Psychology).
// Keys are LESSONS_DATA indices; quiz option order matches LESSONS_DATA.
window.LESSONS_EN = Object.assign(window.LESSONS_EN || {}, {
"14": {"t": "Day Trading Psychology", "s": "FOMO, revenge trading and the most dangerous emotional traps", "cards": [
  {"t": "FOMO (Fear Of Missing Out)", "b": "<p><strong style=\"color:#00FF9D\">FOMO</strong> kicks in when you see an asset's price rising fast and you <strong style=\"color:#00FF9D\">jump in suddenly, without a considered plan</strong>, in the middle of the move — typically right when the move has almost run out of steam.</p>"},
  {"t": "Revenge trading", "b": "<p>After a losing position, many immediately try to <strong style=\"color:#00FF9D\">\"win back\" the loss emotionally, with bigger stakes</strong> — this is revenge trading, statistically one of the most common paths to losing the whole account.</p>"},
  {"t": "The overconfidence trap", "b": "<p>After a few successful trades, the <strong style=\"color:#00FF9D\">false feeling that you have \"cracked\" the market</strong> can easily develop — this often leads to bigger position sizes and looser risk management, exactly when you should be most careful.</p>"},
  {"t": "How do you protect yourself against these?", "b": "<p>The most effective defence is a <strong style=\"color:#00FF9D\">pre-written, documented trading plan</strong> that you follow regardless of your emotional state — including a predefined daily loss limit, on reaching which you simply stop trading for that day.</p>"}],
 "qs": [
  {"q": "Why is psychology critical in day trading?", "o": ["Because psychology only matters for long-term investors", "It continuously requires a series of fast, emotionally loaded decisions", "It isn't critical, only technical analysis really matters", "Because the broker always guarantees emotion-free decision-making"], "e": "Day trading requires a series of fast, emotionally loaded decisions, which is why psychology is critically important."},
  {"q": "What role does fear play in trading?", "o": ["Always fully useful, improving the decision in every situation", "Always improves risk management, the stronger the better", "Never has any effect on decision-making, a completely emotionless process", "It can lead to excessive caution or closing too early"], "e": "Excessive fear can lead to caution or closing too early, preventing good setups from being exploited."},
  {"q": "What role does greed play in trading?", "o": ["It can lead to excessive risk-taking and abandoning the plan", "Always useful, helping to maximise every single profit", "Always reduces risk, the stronger it is, the safer", "Never affects position sizing decisions at all"], "e": "Excessive greed can lead to excessive risk-taking and abandoning the trading plan."},
  {"q": "Why is self-awareness important in this context?", "o": ["It helps recognise our own emotion-driven patterns in time", "Because it only matters for beginners, not at all for experienced traders", "It does not matter, the market always behaves objectively and the same", "Because self-awareness automatically guarantees profit every time"], "e": "Self-awareness helps recognise our own emotion-driven behaviour patterns before they cause damage."},
  {"q": "Why is managing psychology harder than technical analysis?", "o": ["It isn't harder, the two are tasks of exactly equal difficulty", "Because psychology is only theoretical, with no practical significance", "Emotions arise in real time and are hard to control under stress", "Because technical analysis never requires any practice"], "e": "Emotions arise in real time and are hard to control in stressful situations, unlike calm analysis."}]},
"15": {"t": "Discipline and the Trading Plan", "s": "The rules that protect you from yourself", "cards": [
  {"t": "Why write a trading plan down?", "b": "<p>A <strong style=\"color:#00FF9D\">written plan</strong> records your rules in advance, in a calm, emotion-free state (entry conditions, position size, stop-loss, daily limit) — so while trading, under stress, you don't have to decide on the fly, in an emotional state.</p>"},
  {"t": "The most important elements of the plan", "b": "<p>A good plan includes: <strong style=\"color:#00FF9D\">which instruments you trade, on which signal you enter, where the stop-loss and take-profit will be, what the maximum position size is, and what the daily/weekly loss limit is</strong>, on reaching which you stop.</p>"},
  {"t": "Discipline is not the absence of emotion, but following the plan despite emotion", "b": "<p>Many misunderstand discipline — it doesn't mean you feel nothing. It means <strong style=\"color:#00FF9D\">you follow your plan EVEN WHEN you are afraid or excited</strong>, not letting the momentary emotion override the rational decision made in advance.</p>"},
  {"t": "Why is it hard to keep our own rules?", "b": "<p>The hardest part is not <strong style=\"color:#00FF9D\">writing the plan, but sticking to it</strong> in a live market, with real money. Many beginners write an excellent plan, then abandon it at the first bigger loss or gain — which is why it is worth practising discipline with small stakes before risking larger amounts.</p>"}],
 "qs": [
  {"q": "What is the main purpose of a trading plan?", "o": ["Automatically and precisely reducing the broker's commission every day", "Automatically, guaranteed maximising daily profit every time", "Guaranteeing the daily profit", "Rules laid down in advance to avoid emotional decisions"], "e": "The purpose of the trading plan is to provide rules laid down in advance, so we avoid emotion-based decisions."},
  {"q": "What should a good trading plan contain?", "o": ["Entry/exit criteria and risk management rules", "Only how to reach the broker and when its desk is staffed", "A detailed copy of a listed company's annual accounts", "Only the daily profit target, no other element is needed at all"], "e": "A good plan contains the entry/exit criteria and the risk management rules."},
  {"q": "Why is it hard to maintain discipline after a loss?", "o": ["Emotional tension can push us towards impulsive decisions that deviate from the plan", "Because a loss never affects the quality of decision-making", "It isn't hard, a loss always automatically improves discipline", "Because discipline is only relevant in profitable periods"], "e": "The emotional tension caused by a loss can push us towards impulsive decisions that deviate from the plan."},
  {"q": "Why is it worth writing the plan down?", "o": ["Not worth it, it is enough to keep every rule precisely in your head", "Because a written plan automatically guarantees profit every time", "It makes it more concrete and holds us more accountable to ourselves", "Because the law requires every trader to keep a written plan"], "e": "A written plan makes the rules more concrete and holds us more accountable to ourselves."},
  {"q": "What does 'following the plan' mean if a trade loses?", "o": ["It always means the plan was wrong and must be changed", "It means trading must be stopped immediately and for good", "A good decision stays good even if the outcome is bad by chance", "The plan must be discarded immediately and a new one written"], "e": "A good decision stays good even if, by chance, its outcome turned out badly; this doesn't mean the plan is wrong."}]},
"16": {"t": "Keeping a Trading Journal", "s": "How to learn from your own mistakes and successes", "cards": [
  {"t": "Why keep a trading journal?", "b": "<p>A <strong style=\"color:#00FF9D\">trading journal</strong> records every position: when and why you entered, where the stop/limit was, what the result was, and — most importantly — <strong style=\"color:#00FF9D\">what you thought and felt</strong> when making the decision.</p>"},
  {"t": "What should you record for every position?", "b": "<p>At least these are worth noting: <strong style=\"color:#00FF9D\">instrument, entry/exit price, position size, reason for entry (setup), stop-loss/take-profit, result, and a short self-assessment</strong> of whether you followed your own plan.</p>"},
  {"t": "Recognising patterns from the journal", "b": "<p>After a few weeks/months of journaling, <strong style=\"color:#00FF9D\">recognisable patterns</strong> often emerge — e.g. that you regularly lose at a certain time of day, or that your win rate is much better on one setup than another. This self-knowledge is invaluable.</p>"},
  {"t": "The journal as an emotional mirror", "b": "<p>The journal doesn't just record numbers — it also helps <strong style=\"color:#00FF9D\">identify emotional patterns</strong>: e.g. whether you tend towards revenge trading after a losing day, or whether you become overconfident after a winning streak.</p>"}],
 "qs": [
  {"q": "What is the main purpose of the trading journal?", "o": ["Recording the market's official opening hours every day", "Exclusively keeping a precise daily record of the broker's commission", "Collecting objective data to analyse your own performance", "Automatically and instantly calculating the daily profit every time"], "e": "The journal's main purpose is to collect objective data from which your own performance can later be analysed."},
  {"q": "What data is worth recording for every trade?", "o": ["Only the final profit or loss, no other data is needed", "Only the list of the day's news, the trade's details are not needed", "Only the broker's name and the exact time of the trade", "Entry, exit, reasoning and the emotional state too"], "e": "It is worth recording the entry, exit, reasoning and the emotional state at the time."},
  {"q": "Why does the journal help recognise patterns?", "o": ["Because the journal automatically improves future decisions by itself", "It doesn't help, the journal is just a formal, administrative task", "Over time recurring mistakes or strengths become visible", "Because it is only useful for the broker, not for the trader"], "e": "A regularly kept journal can over time reveal recurring mistakes or strengths."},
  {"q": "Why is honesty important when keeping the journal?", "o": ["Self-deception prevents real learning from mistakes", "Because a dishonest journal always automatically shows better results", "Because the broker checks and penalises inaccurate journaling", "It is not important, the content of the journal never really matters"], "e": "Self-deception or selective recording prevents real learning from your own mistakes."},
  {"q": "How often is it worth reviewing the journal?", "o": ["Only when someone complains about our trading", "Only once a year, when preparing the official tax return", "Regularly, e.g. monthly, with an objective review", "Never, it is enough to write it once and then forget it completely"], "e": "It is worth reviewing the journal regularly, e.g. monthly, as part of an objective, data-based review."}]},
"32": {"t": "Confirmation Bias in Trading", "s": "When you only see what you want to see", "cards": [
  {"t": "What is confirmation bias?", "b": "<p><strong style=\"color:#00FF9D\">Confirmation bias</strong> is the tendency to unconsciously seek out and more readily believe information that confirms our existing opinion — while ignoring contradicting signals.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you have already opened a Long position, you may tend to <strong style=\"color:#00FF9D\">only notice the bullish signals</strong> on the chart, while unconsciously playing down the bearish warning signs (e.g. weakening volume, stalling at resistance).</p>"},
  {"t": "Why is this dangerous in position management?", "b": "<p>Because of confirmation bias many <strong style=\"color:#00FF9D\">hold a bad position longer</strong> than they should — interpreting every little signal as confirmation of their expectation, instead of objectively reviewing the decision.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>A useful technique: consciously <strong style=\"color:#00FF9D\">look for the opposing arguments</strong> before/while opening a position — ask yourself: \"What would speak against my decision?\" before looking for signals that confirm your own opinion.</p>"}],
 "qs": [
  {"q": "What is confirmation bias?", "o": ["Actively, consciously searching for contradicting info before every decision", "The tendency to look for info that confirms your own opinion", "An indicator that measures market momentum numerically", "The annual maintenance fee charged by the broker"], "e": "Confirmation bias means unconsciously seeking information that confirms your own, existing opinion."},
  {"q": "How does it appear with an open Long position?", "o": ["We assess signals in both directions equally, in a balanced way", "It doesn't affect daily decision-making in any way", "We only notice the bullish signals and play down the bearish ones", "We consciously only notice the bearish signals everywhere"], "e": "With an open Long position we may tend to notice only the bullish signals."},
  {"q": "Why is it dangerous in position management?", "o": ["It isn't dangerous, it always helps fast decision-making", "It always leads us to faster, more efficient decisions", "We may hold a bad position longer than is justified", "Only a theoretical problem, never relevant in practice"], "e": "Because of it many hold losing positions longer, interpreting every signal as confirmation."},
  {"q": "How can you protect yourself against confirmation bias?", "o": ["Always relying on your first impression, for good", "Consciously looking for the opposing arguments before deciding", "Never looking back at the chart under any circumstances", "Relying only on your own previously formed opinion"], "e": "It is useful to consciously look for the opposing arguments before making a decision."},
  {"q": "Why is it hard to recognise confirmation bias in ourselves?", "o": ["Because it always comes with obvious, instantly noticeable signs", "Because it actually never happens to anyone, anywhere", "Because it only appears in beginner traders", "Because it is a completely unconscious, unnoticed process"], "e": "Confirmation bias is hard to notice because it is an unconscious process."}]},
"33": {"t": "Anchoring Bias — Fixating on a Price", "s": "When a previous price influences you too much", "cards": [
  {"t": "What is anchoring bias?", "b": "<p><strong style=\"color:#00FF9D\">Anchoring bias</strong> is the tendency for an initial piece of information (e.g. a price seen earlier) to lodge as an irrationally strong reference point and distort our further decisions.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you saw a stock at $50 earlier and it is now at $70, you may tend to <strong style=\"color:#00FF9D\">judge it \"expensive\"</strong> simply because you are anchored to $50 — even though the current price and trend give no reason for that conclusion.</p>"},
  {"t": "The \"averaging down\" trap", "b": "<p>A common manifestation of anchoring bias is when someone <strong style=\"color:#00FF9D\">anchors to their own entry price</strong> and \"averages down\" on a losing position (putting in more money at a lower price) just to bring the average price closer to the current price — ignoring the real state of the market.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">start from the CURRENT market situation</strong> in every decision, not from prices seen earlier — ask yourself: \"If I looked at this asset now, with no prior knowledge, what would I do?\"</p>"}],
 "qs": [
  {"q": "What is anchoring bias?", "o": ["An objective decision with no reference point", "A previous piece of info lodging as an excessive reference point", "The trading plan's rules recorded in writing in advance", "Objectively setting the stop-loss level based on the market"], "e": "Anchoring bias means a previous piece of information lodges as an irrationally strong reference point."},
  {"q": "How does it appear with a price?", "o": ["We always assess the price objectively", "It only affects future prices", "Because of a previous price we judge the current one 'expensive' for no reason", "It never influences the decision"], "e": "Because of anchoring, fixated on a price seen earlier, we may judge the current price irrationally."},
  {"q": "What is the 'averaging down' trap?", "o": ["It never relates to anchoring", "Anchored to the entry price, buying more without regard to market reality", "It only happens with profitable positions", "Always a correct strategy in every situation"], "e": "Anchored to the entry price, we keep buying on a loss to improve the average price, ignoring market reality."},
  {"q": "How can you protect yourself against anchoring bias?", "o": ["Always waiting for the same price to come back", "Relying on previous prices", "Never looking at the current price", "Starting from the current market situation"], "e": "It helps to start from the current market situation, not anchored to prices seen earlier."},
  {"q": "Why is this dangerous with a losing position?", "o": ["It isn't dangerous, it always helps the decision", "It can lead to irrational decisions tied to the entry price", "Only a theoretical problem", "It always improves the end result"], "e": "Because of anchoring, fixated on the entry price, we may make irrational decisions instead of following market reality."}]},
"34": {"t": "The Concept of Trading Tilt", "s": "When your emotional state completely takes away your sound judgement", "cards": [
  {"t": "What is trading tilt?", "b": "<p><strong style=\"color:#00FF9D\">Tilt</strong> (a term borrowed from poker) is the state when, after one or more losses/frustrations, the trader becomes <strong style=\"color:#00FF9D\">so emotionally stirred up</strong> that their decisions completely detach from the rational strategy.</p>"},
  {"t": "What are the signs of tilt?", "b": "<p>Typical signs: <strong style=\"color:#00FF9D\">a suddenly increased position size</strong> for no reason, ignoring your own rules (stop-loss, daily limit), and a sudden jump in trading frequency.</p>"},
  {"t": "Why is the tilt state so dangerous?", "b": "<p>In tilt the trader often tries to <strong style=\"color:#00FF9D\">\"fix\" a bad day's loss with a single, riskier trade</strong> — statistically, this behaviour is far more likely to lead to catastrophic damage, far exceeding the whole day's (or a bigger) loss.</p>"},
  {"t": "How do you recognise and manage your own tilt?", "b": "<p>The best defence is <strong style=\"color:#00FF9D\">self-awareness and a pre-decided \"emergency stop\" rule</strong> — e.g. if after two consecutive losing trades you feel you \"want to win back\" the money, that itself is the sign of tilt, and it is time to stop for the day.</p>"}],
 "qs": [
  {"q": "What is trading tilt?", "o": ["The broker's monthly, aggregated, exact commission statement", "A calm, disciplined, planned trading state at all times", "A disciplined, pre-planned trading routine", "An emotional state leading to irrational, impulsive decisions"], "e": "Trading tilt is an emotional state that leads to irrational, impulsive decisions, often after a loss."},
  {"q": "What typically triggers tilt?", "o": ["Frustration caused by one or more losing trades", "Careful, thorough, advance consideration of the day's plan", "A calm, uneventful, completely average trading day", "Regular, disciplined keeping of the trading journal"], "e": "Tilt is typically triggered by frustration caused by one or more losing trades."},
  {"q": "How can the tilt state be recognised in ourselves?", "o": ["If we open a position impulsively, deviating from the plan, after a loss", "If we never feel any emotional reaction while trading", "If we always reduce the stake after every single loss", "If we always follow the pre-written plan precisely"], "e": "Tilt can be recognised when we open a position impulsively, deviating from the plan, after a loss."},
  {"q": "What is the best immediate reaction when tilt is suspected?", "o": ["Changing the strategy immediately and thoughtlessly", "Taking an immediate break, away from trading", "Opening a bigger stake immediately to win it back fast", "Immediately and deliberately ignoring the daily limit"], "e": "The best reaction is to take an immediate break, away from the trading screen."},
  {"q": "Why is it dangerous even for experienced traders?", "o": ["It only happens to beginners, never to experienced traders", "Tilt can affect anyone, regardless of experience", "Because experience always significantly amplifies the effect of tilt", "It isn't dangerous for them, experience always gives full protection"], "e": "Trading tilt can affect anyone, regardless of their level of experience."}]},
"48": {"t": "The Concept of Overtrading", "s": "When too much trading becomes a problem in itself", "cards": [
  {"t": "What is overtrading?", "b": "<p><strong style=\"color:#00FF9D\">Overtrading</strong> is when someone trades far more than necessary, more than the number of good-quality setups — often out of boredom, FOMO, or driven by revenge trading after a loss.</p>"},
  {"t": "Why is it financially expensive too?", "b": "<p>Every extra trade means <strong style=\"color:#00FF9D\">extra spread and commission costs</strong> — many small, unnecessary trades added together can significantly worsen the long-term result, even if each loss is small.</p>"},
  {"t": "Why is it psychologically expensive too?", "b": "<p>Overtrading <strong style=\"color:#00FF9D\">drains focus and discipline</strong> — the more decisions you make in a day, the more tired and impulsive you become, which further worsens decision quality (decision fatigue).</p>"},
  {"t": "How do you recognise the signs of overtrading in yourself?", "b": "<p>If you catch yourself <strong style=\"color:#00FF9D\">trading without a setup, just because you \"want to do something\"</strong>, or your daily trade count far exceeds what you planned, that is a clear sign of overtrading.</p>"}],
 "qs": [
  {"q": "What is overtrading?", "o": ["Exclusively opening large, risky positions", "An indicator that measures daily volume precisely and numerically", "Making far more trades than necessary, often out of boredom", "Making the right number of carefully planned trades"], "e": "Overtrading is when someone trades far more than the number of good setups, often for emotional reasons."},
  {"q": "Why is overtrading financially expensive?", "o": ["Because overtrading always brings extra profit, guaranteed", "Because cost only matters at all for large positions", "Every extra trade means extra spread and commission costs", "It isn't expensive, every trade is always completely free of fees"], "e": "Every extra trade means extra spread and commission costs, which added together can worsen the result."},
  {"q": "What role does 'decision fatigue' play in this?", "o": ["Making many decisions drains focus, worsening quality", "It only causes physical tiredness, it doesn't affect decisions at all", "It always improves decision-making, the more we trade the better", "It does not matter, tiredness never affects anything"], "e": "The more decisions we make, the more tired we become, which worsens the quality of further decisions."},
  {"q": "What is a typical sign of overtrading?", "o": ["Trading rarely, very deliberately, every single time", "Strictly and consistently keeping to the daily loss limit", "Only trading when a real, quality setup is present", "Trading without a setup, just to avoid inactivity"], "e": "A sign of overtrading is making trades without a setup, just to avoid inactivity."},
  {"q": "What is the best defence against overtrading?", "o": ["Making as many trades as possible every day", "Completely and deliberately ignoring the daily limit", "Never analysing our own trading habits at all", "Sticking to concrete setup criteria and a daily trade-count limit"], "e": "Sticking to predefined setup criteria and a daily limit helps avoid overtrading."}]},
"49": {"t": "Recency Bias in Trading", "s": "When the most recent events influence your decision too much", "cards": [
  {"t": "What is recency bias?", "b": "<p><strong style=\"color:#00FF9D\">Recency bias</strong> is the tendency to give disproportionately large weight to the most recent events and experiences in our decisions, at the expense of longer-term patterns.</p>"},
  {"t": "How does it appear after a winning streak?", "b": "<p>After a few consecutive winning trades you may tend to believe that you have <strong style=\"color:#00FF9D\">\"found the winning strategy\"</strong> and carry on with bigger stakes — while the winning streak may just have been luck in a particular market environment.</p>"},
  {"t": "How does it appear after a losing streak?", "b": "<p>Conversely, after a few consecutive losing trades you may tend to <strong style=\"color:#00FF9D\">give up an otherwise statistically good strategy</strong>, just because the most recent results were negative.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It is important to <strong style=\"color:#00FF9D\">evaluate a strategy on a larger sample (across many trades)</strong>, not just on the last few results — even a good strategy can have short losing stretches, and vice versa.</p>"}],
 "qs": [
  {"q": "What is recency bias?", "o": ["Automatically reviewing the risk management rules", "The mathematical relationship between daily volume and price", "Disproportionately weighting the most recent events", "Overweighting old events"], "e": "Recency bias gives disproportionately large weight to the most recent events in decisions."},
  {"q": "How does it appear after a winning streak?", "o": ["We stop trading immediately", "We may believe we have 'found' the sure-fire strategy", "It never affects behaviour", "It always makes us more careful"], "e": "After a winning streak we may tend to open a bigger stake with excessive confidence."},
  {"q": "How does it appear after a losing streak?", "o": ["We always stick with the strategy", "We always increase the stake size", "We raise the stake to win back the loss fast", "We may give up a statistically good strategy"], "e": "After a losing streak we may give up an otherwise good strategy because of the most recent results."},
  {"q": "How can you protect yourself against recency bias?", "o": ["Never analysing the past", "Judging only on the last few trades", "Switching strategy immediately after every loss", "Evaluating on a larger sample, across many trades"], "e": "It is worth evaluating a strategy's performance on a larger sample, across many trades."},
  {"q": "Why is it dangerous to base decisions only on the most recent results?", "o": ["Because old data is never relevant", "It isn't dangerous, the most recent is always the most important", "Even a good strategy can have a short losing stretch", "Because strategies never change"], "e": "Even a statistically good strategy can have short losing stretches that don't mean the strategy is flawed."}]},
"50": {"t": "Loss Aversion in Day Trading", "s": "Why a loss hurts more than a gain pleases us", "cards": [
  {"t": "What is loss aversion?", "b": "<p><strong style=\"color:#00FF9D\">Loss aversion</strong> means that psychologically the pain of a loss of a given size is stronger than the joy of a gain of the same size — this bias deeply influences our trading decisions.</p>"},
  {"t": "How does this lead to bad position-closing decisions?", "b": "<p>Because of loss aversion many <strong style=\"color:#00FF9D\">hold a losing position too long</strong> (hoping it turns around, avoiding \"realising\" the loss), while closing a profitable position too early, afraid the profit will disappear.</p>"},
  {"t": "The \"realised\" vs \"paper\" loss trap", "b": "<p>Many treat a <strong style=\"color:#00FF9D\">paper loss</strong> psychologically differently (as long as you don't close, it \"isn't real\") from a realised one — although financially the situation is exactly the same, only the decision-making is distorted by it.</p>"},
  {"t": "How can you protect yourself against loss aversion?", "b": "<p>A <strong style=\"color:#00FF9D\">predefined, set-in-stone stop-loss</strong> is the most effective defence — it takes the decision out of your hands at the moment when your emotions would try hardest to pull you away from your plan.</p>"}],
 "qs": [
  {"q": "What is loss aversion?", "o": ["The name of an insurance package offered by the broker", "An indicator that precisely measures daily volatility", "Gains and losses always have equally strong emotional effects", "The pain of a loss is stronger than the joy of an equal gain"], "e": "Loss aversion means the pain of a loss is psychologically stronger than the joy of an equal gain."},
  {"q": "How does loss aversion appear with a losing position?", "o": ["It never affects our position management decisions", "We always accept the loss immediately, with discipline", "We always double the stake immediately after the loss", "We hold it too long, hoping it turns around"], "e": "To avoid accepting the loss we may hold a bad position too long."},
  {"q": "How does it appear with a profitable position?", "o": ["We always exploit the whole move to the maximum", "It never affects how a profitable position is managed at all", "We close it too early, afraid of losing the profit", "We hold it patiently until the target price is fully reached"], "e": "Because of the fear of loss we may also close a profitable position too early."},
  {"q": "Why is this behaviour asymmetric?", "o": ["It isn't asymmetric, we behave the same in both directions", "Because the market asymmetrically rewards patient traders", "The fear of loss is stronger than the desire for profit", "Because profit is always more important than avoiding loss"], "e": "The fear of loss has a psychologically stronger effect than the desire for profit."},
  {"q": "How can this be consciously counterbalanced?", "o": ["By holding positions without limit and without planning", "By never using any predefined exit level", "By relying on emotions in every position decision", "With strict stop-loss and take-profit levels fixed in advance"], "e": "Strict stop-loss and take-profit levels fixed in advance help counterbalance the effect of loss aversion."}]},
"64": {"t": "The Sunk Cost Fallacy in Trading", "s": "When money/time already spent pushes you into a bad decision", "cards": [
  {"t": "What is the sunk cost fallacy?", "b": "<p>The <strong style=\"color:#00FF9D\">sunk cost fallacy</strong> is the tendency to keep clinging to a bad decision because of a resource already invested (and not recoverable) — money, time, energy — instead of rationally looking to the future.</p>"},
  {"t": "How does it appear with a losing position?", "b": "<p>\"I've been in this position so long, I can't give up now\" — this thinking <strong style=\"color:#00FF9D\">cites the time/money already invested as justification</strong>, while the decision should be based solely on CURRENT and FUTURE prospects.</p>"},
  {"t": "Why is this economically irrational?", "b": "<p>Money/time already spent <strong style=\"color:#00FF9D\">cannot be recovered, regardless of your next decision</strong> — rational decision-making should only weigh what the best step is FROM NOW ON, independent of past investment.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>A useful technique: <strong style=\"color:#00FF9D\">imagine looking at this position now, with no prior knowledge</strong> — if you had no money in it, would you open such a position now? If the answer is no, that signals the sunk cost fallacy is keeping your current decision alive.</p>"}],
 "qs": [
  {"q": "What is the sunk cost fallacy?", "o": ["The Kelly Criterion method of position sizing", "Clinging to a decision because of money already invested", "An objective decision looking to the future", "Automatically calculating the daily loss limit"], "e": "The sunk cost fallacy means clinging to something because of an already invested, unrecoverable resource."},
  {"q": "How does the sunk cost fallacy appear with a losing position?", "o": ["We close it quickly because the loss bothers us", "We cling to it because of the money tied up, instead of the prospects", "We close the position immediately because of it", "We decide based on future prospects"], "e": "Because of sunk cost we may cling to a position based on the money tied up in it."},
  {"q": "Why is this economically irrational?", "o": ["The spent resource can't be recovered, regardless of the decision", "The market takes the invested time into account", "The past always determines the future", "It isn't irrational, it is always right"], "e": "Money already spent can't be recovered, so the decision should focus only on the future."},
  {"q": "Which technique helps recognise this?", "o": ["Never rethinking the decision", "Looking primarily at the amount invested", "Always following the first decision without change", "Imagining you were looking at the position now, with no prior knowledge"], "e": "It helps to imagine whether, without the past investment, you would open such a position now."},
  {"q": "What should a rational decision be based on?", "o": ["How long the position has been open", "Current and future prospects", "The time and money already invested", "The emotional weight of the decision"], "e": "A rational decision should be based on current and future market prospects, not on past investment."}]},
"65": {"t": "The Gambler's Fallacy in Trading", "s": "When you believe 'this has to happen now'", "cards": [
  {"t": "What is the gambler's fallacy?", "b": "<p>The <strong style=\"color:#00FF9D\">gambler's fallacy</strong> is the mistaken belief that if a random event hasn't happened for a long time, it becomes \"more due\" — while statistically this is usually not true.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>\"I've had 5 losing trades in a row, the next one HAS to be a winner\" — this thinking <strong style=\"color:#00FF9D\">wrongly assumes</strong> that the market \"remembers\" previous results and will compensate.</p>"},
  {"t": "Why is this wrong in most market contexts?", "b": "<p>If your trading decisions are <strong style=\"color:#00FF9D\">independent of each other</strong> (not based on the same setup pattern that could be objectively reviewed), previous results don't statistically influence the outcome of the next trade.</p>"},
  {"t": "Why is this dangerous for stake sizing?", "b": "<p>Under the influence of the gambler's fallacy many <strong style=\"color:#00FF9D\">increase their stake size</strong> after a losing streak, \"taking it for granted\" that the turnaround is near — this can further worsen the loss if the streak continues.</p>"}],
 "qs": [
  {"q": "What is the gambler's fallacy?", "o": ["The real relationship between daily volume and win rate", "The market remembers previous outcomes", "Deliberately tightening risk management rules after a loss", "The mistaken belief that an event that hasn't happened for long becomes 'more due'"], "e": "The gambler's fallacy is the mistaken belief that a random event becomes 'more due' if it hasn't happened for a long time."},
  {"q": "How does the gambler's fallacy appear in day trading?", "o": ["'After so many losses, the next one has to be a winner'", "It only appears after a winning streak", "It never influences decisions", "We always decide objectively, based on data"], "e": "The gambler's fallacy typically appears as believing, after a losing streak, that the next win is 'due'."},
  {"q": "Why is this wrong for independent trades?", "o": ["Previous results don't statistically influence the next one", "It isn't wrong, it is always true", "Because the market deliberately compensates", "Because the fifth trade is always a winner"], "e": "If trades are independent, previous results don't statistically influence the outcome of the next one."},
  {"q": "What danger does this pose for stake sizing?", "o": ["It guarantees correct sizing", "It can lead to increased stakes after a losing streak", "It has no effect on stake size", "It always reduces the stake automatically"], "e": "Under the gambler's fallacy many increase their stake size after a losing streak, worsening the possible loss."},
  {"q": "What distinguishes it from an objective strategy review?", "o": ["It always gives the same result", "It rests on blind faith, not data-based analysis", "It always gives a more accurate result", "Nothing, the two are the same"], "e": "The gambler's fallacy rests on blind, statistically unfounded belief, unlike an objective, data-based review."}]},
"66": {"t": "The Endowment Effect — Clinging to Our Own Positions", "s": "Why we overvalue what we already have", "cards": [
  {"t": "What is the endowment effect?", "b": "<p>The <strong style=\"color:#00FF9D\">endowment effect</strong> is the bias by which we tend to value something more just because we already own it — even if objectively it would be worth the same as if it weren't ours.</p>"},
  {"t": "How does it appear with an open position?", "b": "<p>If you already have a Long position in an asset, you may tend to <strong style=\"color:#00FF9D\">see its prospects more optimistically</strong> than if you looked at it objectively, as an outsider — purely because it is already \"yours\".</p>"},
  {"t": "Why does this make rational position management harder?", "b": "<p>Because of the endowment effect we <strong style=\"color:#00FF9D\">find it harder to recognise</strong> when a position should actually be closed — the feeling of \"ownership\" unconsciously distorts objective assessment.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>As with other biases, it helps to look at your own position <strong style=\"color:#00FF9D\">objectively, with outside eyes</strong>: \"If I didn't have this position today, right now, would I open the same one based on the current information?\"</p>"}],
 "qs": [
  {"q": "What is the endowment effect?", "o": ["Valuing something more because it is already ours", "An objective, emotion-free daily review of the position", "Undervaluing what we have", "Automatically adjusting the stop-loss level based on the market"], "e": "The endowment effect means valuing something more just because we already own it."},
  {"q": "How does the endowment effect appear with an open position?", "o": ["It always makes us more pessimistic", "We see it more optimistically, just because it is already 'ours'", "We see it more pessimistically than someone else's position", "We see its prospects more objectively"], "e": "We may tend to see an open position's prospects more optimistically, purely because of ownership."},
  {"q": "Why does this make rational position management harder?", "o": ["It always leads to an immediate closing decision", "Because we always close the position too early", "We find it harder to recognise when it should be closed", "It doesn't make it harder, it always helps"], "e": "The feeling of ownership can distort objective assessment, making the closing decision harder."},
  {"q": "Which question helps recognise the endowment effect?", "o": ["'How much money did I invest?'", "'How long has it been open?'", "'If I didn't have this position now, would I open it now?'", "'What do others think?'"], "e": "It helps to ask whether, based on current info and without ownership, we would open the same position."},
  {"q": "How is it similar to other biases such as anchoring?", "o": ["They are not similar in any way", "The endowment effect is always stronger", "Only anchoring really exists", "Both unconsciously distort assessment because of a non-rational reference point"], "e": "Both biases distort assessment because of a non-rational reference point (ownership or an old price)."}]}
});

// ---- Part 2: lessons 81–133 ----
Object.assign(window.LESSONS_EN, {
"81": {"t": "The Dunning-Kruger Effect in Trading", "s": "When a beginner overestimates their own knowledge", "cards": [
  {"t": "What is the Dunning-Kruger effect?", "b": "<p>The <strong style=\"color:#00FF9D\">Dunning-Kruger effect</strong> describes how people with little knowledge/experience tend to overestimate their own competence — because they can't even assess how much they still don't know.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>A beginner who, after a few successful trades, <strong style=\"color:#00FF9D\">believes they have \"cracked\" the market</strong> is a classic Dunning-Kruger example — real expertise is built through a lot of experience and many mistakes, not in a few lucky weeks.</p>"},
  {"t": "The typical shape of the \"knowledge curve\"", "b": "<p>The sense of competence often <strong style=\"color:#00FF9D\">shoots up quickly with little knowledge</strong> (\"Mount Stupid\"), then temporarily crashes as real experience builds up (we realise how much we didn't know), before rising gradually and realistically.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to consciously <strong style=\"color:#00FF9D\">treat early successes with humility</strong>, evaluate performance objectively across many trades (see expectancy), and accept that real expertise takes years.</p>"}],
 "qs": [
  {"q": "What is the Dunning-Kruger effect?", "o": ["The statistical relationship between daily volume and experience", "Regular, objective testing of the trading strategy", "Experienced people underestimating themselves", "People with little knowledge overestimating their competence"], "e": "The Dunning-Kruger effect describes how people with little knowledge tend to overestimate their competence."},
  {"q": "How does the Dunning-Kruger effect appear in day trading?", "o": ["It never appears in trading", "It only appears in losing traders", "It only occurs in experienced traders", "A beginner believes after a few trades that they understand the market"], "e": "A beginner who feels after a few successful trades that they fully understand the market is a classic example."},
  {"q": "What is the typical shape of the 'knowledge curve'?", "o": ["It shoots up quickly, then crashes, before rising realistically", "It rises continuously and evenly", "It never changes over time", "It starts at the maximum right away"], "e": "The sense of competence shoots up quickly with little knowledge, then crashes as experience grows."},
  {"q": "How can you protect yourself against the Dunning-Kruger effect?", "o": ["Believing immediately that you know everything", "Never learning any further", "Treating early successes with humility, based on objective data", "Ignoring feedback"], "e": "It helps to treat early successes with humility, evaluating performance objectively across many trades."},
  {"q": "Why aren't a few successful weeks enough for real expertise?", "o": ["Because expertise can never be developed", "Expertise is built through a lot of experience and mistakes", "They are enough, always sufficient evidence", "Because the market never changes"], "e": "Real expertise is built by accumulating a lot of experience and mistakes, not in a few lucky weeks."}]},
"82": {"t": "Herd Mentality", "s": "When you enter because 'everyone else is doing it too'", "cards": [
  {"t": "What is herd mentality?", "b": "<p><strong style=\"color:#00FF9D\">Herd mentality</strong> means following the crowd's behaviour instead of our own analysis — entering a position because \"it looks like everyone else is doing it\".</p>"},
  {"t": "How does it appear in the age of social media?", "b": "<p>Trader forums and social platforms can <strong style=\"color:#00FF9D\">amplify this effect</strong> — if many people talk enthusiastically about an asset, you can easily get caught up in the crowd's mood, without objective analysis.</p>"},
  {"t": "Why is this dangerous right at the top/bottom?", "b": "<p>By the time \"everyone is talking\" about a move and herd mentality peaks, <strong style=\"color:#00FF9D\">a significant part of the move has already happened</strong> — late entrants often get in exactly when the early players are realising profits and getting out.</p>"},
  {"t": "How can you protect yourself against herd mentality?", "b": "<p>Always ask yourself: <strong style=\"color:#00FF9D\">\"If I hadn't heard other people's opinions, would I enter based on my own analysis?\"</strong> — if the answer is no, that may signal your decision rests on the crowd's mood, not objective analysis.</p>"}],
 "qs": [
  {"q": "What is herd mentality?", "o": ["Following the crowd's behaviour instead of your own analysis", "The official trading strategy recommended by the broker", "Relying on your own, objective analysis", "Regular, objective keeping of the trading journal"], "e": "Herd mentality means following the crowd's behaviour instead of your own analysis."},
  {"q": "How can social media amplify it?", "o": ["It always makes us more objective", "Many get excited about an asset, which can sweep us into the crowd's mood", "It has no effect on it", "It always reduces its effect"], "e": "Forums and social platforms can amplify the effect of herd mentality."},
  {"q": "Why is it dangerous to enter once 'everyone is talking' about a move?", "o": ["A significant part of the move may already have happened", "The market always halts at such times", "It isn't dangerous, it is always a sure profit", "The broker forbids entering"], "e": "By the time everyone talks about a move, a significant part may have happened and early players may be cashing in."},
  {"q": "Which question can help recognise herd mentality?", "o": ["'How many people are talking about this?'", "'Would I enter based on my own analysis, without others?'", "'When did the company announce the news?'", "'How long has the asset existed?'"], "e": "It helps to ask whether we would enter based on our own analysis, without other people's opinions."},
  {"q": "Why is this especially dangerous in day trading?", "o": ["It isn't dangerous, it always helps", "It is only relevant in the long term", "Because herd mentality always reduces volatility", "Fast, mass decisions can amplify bubble-like moves"], "e": "Fast decisions made en masse, without analysis, can amplify volatility and bubble-like moves."}]},
"83": {"t": "Self-Serving Bias in Trading", "s": "When a profit is 'skill' and a loss is 'bad luck'", "cards": [
  {"t": "What is self-serving bias?", "b": "<p><strong style=\"color:#00FF9D\">Self-serving bias</strong> is the tendency to attribute our successes to our own ability and our failures to external factors (bad luck, market manipulation).</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>On a winning trade: <strong style=\"color:#00FF9D\">\"I did a brilliant analysis\"</strong> — on a losing trade: <strong style=\"color:#00FF9D\">\"The market was manipulated\" or \"I was unlucky\"</strong>. This distorted narrative prevents real learning.</p>"},
  {"t": "Why does this hinder progress?", "b": "<p>If you <strong style=\"color:#00FF9D\">attribute every loss to external causes</strong>, you never objectively examine your own decision-making mistakes — this prevents you from learning from them and improving.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>The <strong style=\"color:#00FF9D\">trading journal</strong> (which you learned about earlier) is a good antidote to exactly this bias too — objective, written facts (what you decided, why, what happened) are harder to rewrite afterwards into a more comfortable narrative.</p>"}],
 "qs": [
  {"q": "What is self-serving bias?", "o": ["Attributing successes to outside causes and failures to yourself", "Deliberate, conscious manipulation of the market against us", "Attributing successes to yourself and failures to outside causes", "Always exclusively the broker's responsibility"], "e": "Self-serving bias means attributing successes to your own ability and failures to external factors."},
  {"q": "How does it appear on a losing trade?", "o": ["It never affects self-assessment", "'My analysis was brilliant'", "Always objective self-assessment", "'The market was manipulated', instead of admitting your own mistake"], "e": "On a losing trade, because of self-serving bias we may tend to cite external causes."},
  {"q": "Why does it hinder progress?", "o": ["It has no effect on progress", "It always leads to objective self-assessment", "We don't objectively examine our own mistakes", "It doesn't hinder it, it always helps"], "e": "If we attribute every loss to external causes, we don't learn from our own mistakes."},
  {"q": "Why is the journal a good antidote?", "o": ["It doesn't help at all", "Because the journal always proves us right", "Because the journal fixes things automatically", "Objective facts written down earlier are harder to rewrite afterwards"], "e": "The journal's objective, previously recorded facts are harder to rewrite into a self-serving narrative."},
  {"q": "Why is recognising this important for real learning?", "o": ["It always improves the result immediately", "Because learning always comes from external feedback", "Real learning can only come from honest self-assessment", "It has no significance for progress"], "e": "Real learning and progress can only come from objective, honest self-assessment."}]},
"93": {"t": "Analysis Paralysis", "s": "When too much analysis prevents the decision", "cards": [
  {"t": "What is analysis paralysis?", "b": "<p><strong style=\"color:#00FF9D\">Analysis paralysis</strong> is the state where someone tries to take so many indicators, timeframes and factors into account at once that in the end they can't make any decision — the opportunity disappears before they feel \"sure\".</p>"},
  {"t": "Why do too many indicators at once lead to this?", "b": "<p>If you watch <strong style=\"color:#00FF9D\">5–6 different indicators</strong> at once, it is almost guaranteed that some of them will give contradicting signals — this paralyses decision-making instead of helping it.</p>"},
  {"t": "The \"perfect setup\" trap", "b": "<p>Many wait so long for a <strong style=\"color:#00FF9D\">\"perfect\" setup, confirmed from every angle</strong>, that in reality they rarely or never enter — in the market there will never be 100% certainty, only probabilities.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to simplify your entry rules <strong style=\"color:#00FF9D\">in advance, to a few concrete, simple criteria</strong> — fewer but well-understood tools often lead to more effective decision-making than too many superficially known indicators.</p>"}],
 "qs": [
  {"q": "What is analysis paralysis?", "o": ["Fast, ill-considered decision-making in every situation, immediately", "Too much analysis prevents decision-making", "The minimum trading balance set by the broker", "An indicator that measures daily momentum precisely and numerically"], "e": "Analysis paralysis is the state where too much analysis prevents decision-making."},
  {"q": "Why can many indicators lead to analysis paralysis?", "o": ["Because every indicator always shows exactly the same thing", "Because many indicators always significantly speed up the decision", "It never leads to this, it always helps fast decisions", "Indicators often give contradicting signals"], "e": "Many indicators giving contradicting signals can paralyse decision-making."},
  {"q": "What is the 'perfect setup' trap?", "o": ["The perfect setup is always instantly recognisable to everyone", "In the market there will never be full certainty, only probabilities", "No such trap exists in reality, ever", "It is always easy to find the perfect setup immediately"], "e": "There is never full certainty in the market, so waiting for the perfect setup can lead to missing out."},
  {"q": "How can you protect yourself against analysis paralysis?", "o": ["By simplifying entry to a few simple, concrete criteria", "By adding as many indicators as possible to every decision", "By always deciding at the last moment, with no analysis at all", "By never analysing anything, always deciding purely on instinct"], "e": "It helps to simplify entry rules to a few simple, well-understood criteria."},
  {"q": "Why can using fewer tools be more effective?", "o": ["There is no relationship between the number of tools and decision quality", "Because fewer tools always guarantee a more accurate result", "It can't be more effective, more tools are always the better solution", "It reduces the confusion and paralysis caused by contradicting signals"], "e": "Fewer but well-understood tools reduce the confusion caused by contradicting signals."}]},
"94": {"t": "Boredom Trading", "s": "When boredom, not a setup, drives you into a position", "cards": [
  {"t": "What is boredom trading?", "b": "<p><strong style=\"color:#00FF9D\">Boredom trading</strong> happens when someone enters a position not because of a real, quality setup, but because they are <strong style=\"color:#00FF9D\">bored and \"something has to happen\"</strong>.</p>"},
  {"t": "When is this phenomenon most common?", "b": "<p>Boredom trading often appears in <strong style=\"color:#00FF9D\">slow, low-volatility periods</strong> (e.g. the midday lull), when there are no real, quality opportunities in the market.</p>"},
  {"t": "Why is it hard to recognise in ourselves?", "b": "<p>Boredom trading <strong style=\"color:#00FF9D\">often appears rationalised</strong> — afterwards we easily invent a \"technical reason\" for the entry, although it was really boredom, not a real setup, that drove the decision.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">consciously accept</strong> that not every day and not every hour is suitable for trading — a good day trader can wait patiently until a real, quality setup appears, instead of acting just to avoid inactivity.</p>"}],
 "qs": [
  {"q": "What is boredom trading?", "o": ["A trade always based on a carefully planned, quality setup", "The name of the broker's entertaining, free demo programme", "An indicator that measures daily volatility precisely and numerically", "Making a trade purely to chase away boredom, without a setup"], "e": "Boredom trading means making a trade just to chase away boredom, without a real setup."},
  {"q": "When does this typically appear?", "o": ["Only when the trader is already in a losing position", "In slow, uneventful market phases when there is no real opportunity", "Only when a real, quality setup appears", "Only at the weekend, when the market is closed anyway"], "e": "Boredom trading typically appears in slow, uneventful market phases when there is no real opportunity."},
  {"q": "Why does this worsen the long-term result?", "o": ["Because trades made out of boredom are always guaranteed profitable", "Because the market always rewards activity, regardless of quality", "It doesn't worsen it, it always improves overall performance", "Trades without a setup statistically bring a worse win rate"], "e": "Trades made out of boredom, without a setup, statistically result in a worse win rate."},
  {"q": "How can boredom trading be recognised in ourselves?", "o": ["If we notice that we 'want to do something' without a setup", "If we never open a position at all under any circumstances", "If we only ever enter quality, pre-identified setups", "If we always follow the pre-written trading plan precisely"], "e": "Boredom trading can be recognised when we notice that we 'want to do something', without a real setup."},
  {"q": "What can help against this?", "o": ["Watching as many screens and charts as possible, continuously", "Setting ourselves a mandatory minimum number of daily trades", "Consciously and completely rejecting patience and discipline", "Accepting that an uneventful, skipped day can be a good day"], "e": "It is important to accept that an uneventful day without trading can be a good, disciplined day."}]},
"100": {"t": "The Illusion of Control in Trading", "s": "When we believe we control what we actually don't", "cards": [
  {"t": "What is the illusion of control?", "b": "<p>The <strong style=\"color:#00FF9D\">illusion of control</strong> is the bias of overestimating how much we can influence the outcome of a fundamentally unpredictable process that also contains random elements.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>After a few successful trades the feeling can easily develop that you <strong style=\"color:#00FF9D\">\"control\" the market</strong> — while in reality you only control your own entry/exit decisions, never the market price itself.</p>"},
  {"t": "Why is this dangerous for risk-taking?", "b": "<p>Under the illusion of control many trade <strong style=\"color:#00FF9D\">with bigger stakes and looser risk management</strong>, because they unconsciously believe they can control the outcome better than is actually possible.</p>"},
  {"t": "How does accepting reality help?", "b": "<p>Accepting that <strong style=\"color:#00FF9D\">you only control your own decisions and your risk management</strong>, not the market outcome itself, helps form more realistic expectations and maintain disciplined risk management even after a winning streak.</p>"}],
 "qs": [
  {"q": "What is the illusion of control?", "o": ["Overestimating how much we can steer a random process", "The market's actual, measurable level of liquidity", "Always applying risk management consciously and strictly", "Real, complete control of the market"], "e": "The illusion of control means overestimating how much we can influence the outcome of an unpredictable process."},
  {"q": "How does it appear after a few successful trades?", "o": ["We become more careful and reduce the stake", "It always leads to increased caution", "It leads to immediate withdrawal", "As the feeling that you control the market"], "e": "After a few successful trades the false feeling that you control the market can easily develop."},
  {"q": "Why is this dangerous for risk-taking?", "o": ["It isn't dangerous, it always improves things", "Because it makes us more careful and restrained", "Because it always leads to smaller stakes", "It can lead to bigger stakes because of overconfidence"], "e": "The illusion of control can lead to bigger stakes and looser risk management."},
  {"q": "What can a day trader really control?", "o": ["Their own decisions and risk management", "The market price itself, directly", "The timing of the news", "The behaviour of other participants"], "e": "A day trader can really only control their own decisions and risk management."},
  {"q": "Why is it useful to accept the limits of control?", "o": ["It has no practical use", "It helps maintain more realistic expectations and discipline", "It isn't useful, it is better to believe everything is controllable", "It always reduces motivation"], "e": "Accepting the real limits of control helps maintain disciplined risk management even after success."}]},
"109": {"t": "Normalcy Bias in Trading", "s": "When we ignore warning signs because 'it has been fine so far'", "cards": [
  {"t": "What is normalcy bias?", "b": "<p><strong style=\"color:#00FF9D\">Normalcy bias</strong> is the tendency to underestimate the probability and impact of an unusual, potentially dangerous event because <strong style=\"color:#00FF9D\">\"everything has always been fine so far\"</strong>.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If a strategy has worked well for a long time, you may tend to <strong style=\"color:#00FF9D\">ignore the warning signs</strong> (e.g. changed market conditions), because you have got used to \"this always works\".</p>"},
  {"t": "Why is this dangerous at a market regime change?", "b": "<p>Markets sometimes <strong style=\"color:#00FF9D\">change fundamentally</strong> (e.g. from low volatility to high) — because of normalcy bias many cling too long to a strategy that no longer works, because the old pattern became familiar.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">regularly and consciously ask yourself</strong>: \"What has changed in the market lately? Are the assumptions I built my strategy on still valid?\"</p>"}],
 "qs": [
  {"q": "What is normalcy bias?", "o": ["Regular, scheduled testing of the strategy", "Overestimating future risks", "Consciously and continuously tightening risk management", "Underestimating the probability of an unusual event"], "e": "Normalcy bias means underestimating an unusual, dangerous event because everything has been fine so far."},
  {"q": "How does it appear with a well-working strategy?", "o": ["We always recognise the change immediately", "We may ignore the warning signs", "We stop the strategy immediately", "We modify the strategy too often"], "e": "If a strategy has worked for a long time, we may tend to ignore the signs of change."},
  {"q": "Why is this dangerous at a regime change?", "o": ["Many cling too long to a strategy that no longer works", "It isn't dangerous, the market never changes", "Because a regime change is always obvious", "It always improves the decision"], "e": "Markets can sometimes change fundamentally, and because of normalcy bias we may cling to the old strategy too long."},
  {"q": "Which question helps recognise normalcy bias?", "o": ["'How much money have I made so far?'", "'What has changed in the market, are my assumptions still valid?'", "'How many people use this strategy?'", "'How long have I been using this?'"], "e": "It helps to ask what has changed in the market and whether the strategy's assumptions are still valid."},
  {"q": "Why is it hard to recognise normalcy bias in ourselves?", "o": ["Habit unconsciously reduces vigilance", "It is always easy to recognise", "No such phenomenon exists", "It only happens to beginners"], "e": "Habit can unconsciously reduce vigilance towards changed conditions."}]},
"110": {"t": "Perfectionism in Trading", "s": "When striving for flawlessness paralyses action", "cards": [
  {"t": "How does perfectionism appear in day trading?", "b": "<p>The <strong style=\"color:#00FF9D\">perfectionist trader</strong> often analyses too long before entering (see analysis paralysis), or punishes themselves unrealistically harshly after every small, unavoidable mistake.</p>"},
  {"t": "Why is flawlessness an unrealistic expectation in trading?", "b": "<p>Even the <strong style=\"color:#00FF9D\">best trading strategies</strong> lose on a significant share of trades — a loss is not a mistake, but a natural, unavoidable part of how statistics work.</p>"},
  {"t": "How does this lead to excessive self-criticism and tilt?", "b": "<p>If you experience every losing trade as a <strong style=\"color:#00FF9D\">personal failure</strong>, instead of seeing it as part of the statistical process, you can easily slip into the trading tilt state learned earlier.</p>"},
  {"t": "How do you find a healthy balance?", "b": "<p>The goal is not <strong style=\"color:#00FF9D\">flawless trading</strong>, but following a CONSISTENT, disciplined process — a good decision and a good result are not always the same; a well-made decision can also end in a loss.</p>"}],
 "qs": [
  {"q": "How does perfectionism appear in day trading?", "o": ["The trader accepts uncertainty and always acts in time", "It never affects the timing of trading decisions at all", "Waiting for the perfect entry, the trader misses the real opportunity", "Perfectionism always significantly improves the speed of decisions"], "e": "Waiting for the perfect entry, the perfectionist trader often misses the real, good opportunity."},
  {"q": "Why is beating yourself up after a missed, slightly worse-timed trade a problem?", "o": ["It isn't a problem, it is always useful and productive", "Only a theoretical problem, with no practical effect ever", "It always immediately and significantly improves the next decision", "It needlessly worsens your mood instead of learning from the situation"], "e": "Beating yourself up needlessly worsens your mood instead of constructively learning from the situation."},
  {"q": "What is the market's real nature compared to perfection?", "o": ["The perfect setup is always clearly and instantly recognisable to everyone", "There is no relationship between the market's nature and perfectionism", "There will never be full certainty in the market, only probabilities", "The market always offers perfect, risk-free entry points"], "e": "There is never full certainty in the market; you can only work with probabilities."},
  {"q": "How does a 'good enough' mindset help?", "o": ["It always significantly worsens trading quality and results", "It allows action at a realistically good, though not perfect, point", "It doesn't help, you must always strive for perfection at any cost", "It is only useful for beginners, not at all for experienced traders"], "e": "A 'good enough' mindset allows action at a realistically good, though not perfect, entry point."},
  {"q": "Why is this important for discipline?", "o": ["It isn't important, discipline has nothing to do with perfectionism", "It only affects risk management, not discipline at all", "Perfectionism always means maximum discipline", "Excessive perfectionism is also a kind of indiscipline, just in another form"], "e": "Excessive perfectionism can also be a kind of indiscipline, because it prevents following the plan."}]},
"121": {"t": "Escalation of Commitment", "s": "When you dig yourself ever deeper into a bad decision", "cards": [
  {"t": "What is escalation of commitment?", "b": "<p><strong style=\"color:#00FF9D\">Escalation of commitment</strong> is the phenomenon where, after a bad decision, instead of stepping back we invest EVER MORE into it — hoping this will justify the original decision.</p>"},
  {"t": "How is this different from the sunk cost fallacy?", "b": "<p>While the sunk cost fallacy describes <strong style=\"color:#00FF9D\">passive clinging</strong> (I won't give up because I've already invested a lot), escalation of commitment means <strong style=\"color:#00FF9D\">active, escalating investment</strong> (I put in even more to prove myself right).</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>With a losing position, instead of accepting the loss, you <strong style=\"color:#00FF9D\">add to the position again and again</strong> (\"averaging down\", but with ever bigger stakes), hoping this will finally justify your original analysis.</p>"},
  {"t": "Why is this especially dangerous because of the growing stake?", "b": "<p>Escalation of commitment can <strong style=\"color:#00FF9D\">increase risk exponentially</strong> — every addition means a bigger stake, which in a market moving the wrong way can lead to a catastrophic loss.</p>"}],
 "qs": [
  {"q": "What is escalation of commitment?", "o": ["Recording the trading plan in writing, mandatorily", "Investing ever more into a bad decision, to justify yourself", "The simple ratio of daily volume to the closing price", "Stepping back immediately after a bad decision"], "e": "Escalation of commitment is investing ever more into a bad decision, hoping it will justify the original choice."},
  {"q": "How is this different from the sunk cost fallacy?", "o": ["Sunk cost is passive clinging, this is active, escalating investment", "It never actually happens", "It is always less dangerous", "In no way, the two are the same"], "e": "The sunk cost fallacy is passive clinging; escalation is active, escalating investment to justify the bad decision."},
  {"q": "How does escalation of commitment appear with a losing position?", "o": ["With an immediate, disciplined close", "We add to the position with ever bigger stakes", "We exit the trade right away", "We always reduce the position size"], "e": "We add to the losing position with ever bigger stakes, hoping to justify the original analysis."},
  {"q": "Why is it especially dangerous because of the growing stake?", "o": ["It isn't dangerous, it always reduces risk", "It can increase risk exponentially with every addition", "It always brings an immediate profit", "It reduces the capital needed"], "e": "Every addition means a bigger stake in a position already going the wrong way, increasing risk exponentially."},
  {"q": "What is the best defence against escalation of commitment?", "o": ["Investing as much as possible into the decision", "Ignoring the loss", "A strict stop-loss and position size limit set in advance", "Never analysing decisions"], "e": "A strict stop-loss and position size limit set in advance help avoid the escalation trap."}]},
"122": {"t": "Apophenia — Seeing Patterns in Random Data", "s": "When the chart 'speaks' to you, but it is only noise", "cards": [
  {"t": "What is apophenia?", "b": "<p><strong style=\"color:#00FF9D\">Apophenia</strong> is the human tendency to see meaningful patterns and connections even in data that is actually random or has no real relationship.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you stare at a chart long enough, you can easily <strong style=\"color:#00FF9D\">\"recognise\" patterns</strong> that are really just random price fluctuations — the human brain is strongly inclined to look for patterns, even where there are none.</p>"},
  {"t": "Why is this especially dangerous on short timeframes?", "b": "<p>The <strong style=\"color:#00FF9D\">shorter the timeframe</strong> (e.g. a 1-minute chart), the larger the share of \"noise\" (random fluctuation with no real meaning) in the move relative to the real signal, which raises the risk of apophenia.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to stick to <strong style=\"color:#00FF9D\">objective, predefined criteria</strong> (e.g. concrete indicator values, volume thresholds), instead of subjectively looking for patterns on the chart \"by eye\".</p>"}],
 "qs": [
  {"q": "What is apophenia?", "o": ["The tendency to see patterns in random data", "Systematic, objective testing of the trading strategy", "Objective, scientific identification of patterns", "The mathematically proven relationship between daily volume and price"], "e": "Apophenia is the tendency to see meaningful patterns even in data that is actually random."},
  {"q": "How does apophenia appear in day trading?", "o": ["It never happens in trading", "We 'see' a pattern on the chart that is just random fluctuation", "It always leads to objective analysis", "We consider every pattern random"], "e": "The trader may 'see' patterns on the chart that are really just random fluctuations."},
  {"q": "Why is it more dangerous on a shorter timeframe?", "o": ["It isn't more dangerous, the risk is the same", "Short timeframes never show patterns", "Long timeframes are always less reliable", "A short timeframe contains more 'noise' relative to signal"], "e": "The shorter the timeframe, the larger the share of noise, which raises the risk of apophenia."},
  {"q": "How can you protect yourself against apophenia (seeing patterns in randomness)?", "o": ["Always relying on gut feeling", "Sticking to objective, predefined criteria", "Staring at the chart as long as possible", "Never using an indicator"], "e": "Sticking to objective, predefined criteria helps avoid the apophenia trap."},
  {"q": "Why is the human brain prone to this?", "o": ["It only happens in certain people", "It is strongly inclined to look for patterns where there are none", "It is a learned, not innate, tendency", "Because it is always perfectly rational"], "e": "The human brain is strongly inclined to look for and find patterns, even in data with no real connection."}]},
"132": {"t": "The Zeigarnik Effect — The Unclosed Position Haunts You", "s": "Why it is hard not to think about a trade that is still open", "cards": [
  {"t": "What is the Zeigarnik effect?", "b": "<p>The <strong style=\"color:#00FF9D\">Zeigarnik effect</strong> describes how the human brain remembers and keeps \"occupying\" itself with UNFINISHED tasks much more than with completed ones.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>An <strong style=\"color:#00FF9D\">open position</strong> \"occupies\" your attention mentally much more than a closed one — this may explain why it is hard to concentrate on anything else while a trade is open.</p>"},
  {"t": "Why can this lead to bad decisions?", "b": "<p>Because of the mental \"pressure\" of the open position you may tend to <strong style=\"color:#00FF9D\">close too early</strong> (just to get rid of the tension), or conversely, to <strong style=\"color:#00FF9D\">dwell on it excessively</strong>, neglecting other important tasks.</p>"},
  {"t": "How can you manage this consciously?", "b": "<p>If you know an open position <strong style=\"color:#00FF9D\">\"occupies\" you mentally</strong>, it can help to rely on pre-set stop-loss/take-profit levels instead of anxiously watching the position continuously — this reduces the stress caused by the Zeigarnik effect.</p>"}],
 "qs": [
  {"q": "What is the Zeigarnik effect?", "o": ["Remembering finished tasks better", "Better recall of and preoccupation with unfinished tasks", "A kind of stop-loss strategy", "Completed tasks staying more vividly in mind"], "e": "The Zeigarnik effect describes how we remember better and stay preoccupied with an unfinished task."},
  {"q": "How does the Zeigarnik effect appear with an open position?", "o": ["It never affects concentration", "An open position ties up attention mentally more", "It only appears with losing positions", "A closed trade occupies attention more"], "e": "An open position ties up attention mentally more than an already closed trade."},
  {"q": "Which bad decision can this lead to?", "o": ["Always to a more objective decision", "Always to longer, more considered holding", "Closing too early or dwelling on the position excessively", "Always to closing too late"], "e": "Because of the mental pressure we may tend to close too early or dwell on the position excessively."},
  {"q": "How can this be managed consciously?", "o": ["By ignoring the position", "With pre-set stop/take-profit levels", "By continuous, anxious watching", "By opening as many positions at once as possible"], "e": "Relying on pre-set stop-loss/take-profit levels can reduce the need for continuous watching."},
  {"q": "What kind of phenomenon is the Zeigarnik effect in general?", "o": ["A widely researched, general feature of human cognition", "It only occurs in day traders", "It only exists in certain cultures", "A rare phenomenon found only among traders"], "e": "The Zeigarnik effect is a general, widely researched feature of human cognition."}]},
"133": {"t": "The Risks of Copy Trading", "s": "When you copy other people's positions — blindly", "cards": [
  {"t": "What is copy trading?", "b": "<p><strong style=\"color:#00FF9D\">Copy trading</strong> is a service where you automatically copy the positions of another trader, typically advertised as \"successful\", with your own capital.</p>"},
  {"t": "Why is blind following dangerous?", "b": "<p>If you don't understand <strong style=\"color:#00FF9D\">WHY the copied trader opens a given position</strong>, you can't prepare when the strategy starts to lose, and you can't judge when you should stop copying.</p>"},
  {"t": "Why is the displayed past performance misleading?", "b": "<p>The <strong style=\"color:#00FF9D\">spectacular past returns</strong> shown on copy trading platforms are often selectively chosen or reflect a lucky, short period — the same risks apply to them as to any \"sure tip\".</p>"},
  {"t": "How can you use it more wisely if you do try it?", "b": "<p>If you try copy trading, it is worth applying <strong style=\"color:#00FF9D\">your own strict risk management</strong> on top (e.g. a maximum amount you dedicate to it) — never entrust your whole capital to a single strategy controlled by someone else.</p>"}],
 "qs": [
  {"q": "What is copy trading?", "o": ["Sharing the trading journal with another user", "Automatically copying another trader's positions", "Your own independent backtest of the strategy before copying", "Trading based on your own, independent analysis"], "e": "Copy trading automatically copies another trader's positions with your own capital."},
  {"q": "Why is blind following dangerous?", "o": ["Because the followed trader always decides badly", "Only institutions can use it", "If you don't understand the reason, you can't prepare for the loss", "Copy trading is always illegal"], "e": "If you don't understand why the copied trader opens a position, you can't prepare for the losing period."},
  {"q": "Why is the displayed past performance misleading?", "o": ["Platforms are legally required to lie", "It is never misleading", "Past data is never relevant", "It is often selectively chosen, reflecting a lucky period"], "e": "The displayed returns are often selectively chosen or reflect a lucky period."},
  {"q": "What is worth doing if you do try it?", "o": ["Entrusting all your capital to it", "Automatically accepting every position", "Never checking the copied trader", "Applying your own risk management on top, with a limited amount"], "e": "It is worth applying your own risk management, never entrusting all your capital to a single strategy controlled by others."},
  {"q": "Why is it important to understand the copied strategy's logic?", "o": ["It does not matter, copying blindly is enough", "Without it copy trading doesn't even work technically", "The law requires understanding it", "It helps you prepare and recognise when to stop copying"], "e": "Understanding the logic helps prepare for losing periods and stop copying in time."}]}
});

// ---- Part 3: lessons 143–196 ----
Object.assign(window.LESSONS_EN, {
"143": {"t": "Guru Following and Group Bias", "s": "When you treat an 'expert's' word as unquestionable", "cards": [
  {"t": "What is guru following?", "b": "<p><strong style=\"color:#00FF9D\">Guru following</strong> develops when a trader blindly, uncritically accepts every recommendation of someone considered an \"expert\" (influencer, analyst), without understanding or questioning them themselves.</p>"},
  {"t": "Why is this psychologically attractive?", "b": "<p>Your own analysis is <strong style=\"color:#00FF9D\">laborious and carries uncertainty</strong> — it is much more comfortable to rely on a confident \"expert\" than to bear the responsibility and doubts of your own decision-making.</p>"},
  {"t": "Why is this specifically dangerous?", "b": "<p>If you blindly follow someone and their tip goes wrong, <strong style=\"color:#00FF9D\">you learn nothing from it</strong> — you don't understand why the decision was bad, so you can't avoid a similar mistake next time.</p>"},
  {"t": "How can you use other people's opinions wisely?", "b": "<p>It is worth treating other people's analysis <strong style=\"color:#00FF9D\">as an input, not a command</strong> — understand the REASONING behind it, review it based on your own knowledge, and only act if your own analysis supports it too.</p>"}],
 "qs": [
  {"q": "What is guru following?", "o": ["Objective, numerical analysis of backtesting results", "Regular, critical review of the trading journal", "Applying your own, critical analysis", "Blindly accepting every piece of advice from an expert"], "e": "Guru following is the blind, uncritical acceptance of an 'expert's' recommendations."},
  {"q": "Why is this psychologically attractive?", "o": ["Your own analysis is laborious; relying on a confident expert is more comfortable", "Gurus are never wrong", "Your own analysis is always easier", "The law requires following them"], "e": "Your own analysis is laborious and uncertain; it is more comfortable to follow a confident expert."},
  {"q": "Why is blind guru following dangerous?", "o": ["Gurus never give advice", "Because the guru always gives bad tips", "If the tip goes wrong, we learn nothing from it", "Because gurus never share tips"], "e": "If we blindly follow someone and it goes wrong, we learn nothing, because we don't understand why."},
  {"q": "How is it worth treating other people's opinions?", "o": ["As an input that we review based on our own knowledge", "Ignoring them completely", "Accepting them only from famous people", "Following them as blind commands"], "e": "It is worth treating other people's analysis as an input, reviewed with your own knowledge before acting."},
  {"q": "What is the difference between learning and guru following?", "o": ["Learning is never useful", "Guru following is critical, learning is blind acceptance", "Guru following is always more effective", "Learning evaluates critically, guru following accepts blindly"], "e": "Learning evaluates information critically; guru following accepts it blindly, without criticism."}]},
"144": {"t": "Optimism Bias in Trading", "s": "When we always believe the bad outcome can't happen to us", "cards": [
  {"t": "What is optimism bias?", "b": "<p><strong style=\"color:#00FF9D\">Optimism bias</strong> is the tendency to systematically underestimate the probability of negative events happening to us, while overestimating that of positive ones.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>\"I know most beginner traders lose, but <strong style=\"color:#00FF9D\">I'll be different</strong>\" — this thinking is classic optimism bias, which can lead to unrealistic expectations and insufficient risk management.</p>"},
  {"t": "Why is it hard to recognise in ourselves?", "b": "<p>Optimism bias <strong style=\"color:#00FF9D\">works unconsciously</strong> — most people who hear the statistics (e.g. most day traders lose in the long run) automatically think they will be the exception.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">treat the statistics consciously and objectively</strong> — not to take away your motivation, but so you approach trading with realistic expectations and proper risk management, not reckless optimism.</p>"}],
 "qs": [
  {"q": "What is optimism bias?", "o": ["Automatically making risk management rules stricter", "Overestimating negative events", "The market's actual, measured level of volatility", "Underestimating negative events and overestimating positive ones"], "e": "Optimism bias means underestimating the probability of negative events while overestimating positive ones."},
  {"q": "How does optimism bias appear in day trading?", "o": ["'I know many lose, but I'll be the exception'", "'I'm bound to lose, so I won't even try'", "'Losing is certain for me, just like for everyone'", "'I'll end up in the red like everybody else'"], "e": "The classic form of optimism bias: we acknowledge the unfavourable statistics but think we are the exception."},
  {"q": "Why is it hard to recognise in ourselves?", "o": ["Because it doesn't exist", "It works unconsciously; the feeling of being the exception is automatic", "It is always obvious", "It only occurs in certain professions"], "e": "It works unconsciously; most people automatically consider themselves an exception to the statistics."},
  {"q": "How can you protect yourself against optimism bias?", "o": ["By thinking as optimistically as possible", "By never analysing your chances", "By ignoring the statistics", "By treating the statistics objectively, with realistic expectations"], "e": "Forming objective, realistic expectations helps with proper risk management."},
  {"q": "What can its consequence be for risk management?", "o": ["Insufficient risk management, because we underestimate the chance of loss", "It leaves risk management untouched", "It always becomes stricter", "It automatically reduces stake size"], "e": "Optimism bias can lead to insufficient risk management, underestimating the chance of an unfavourable outcome."}]},
"154": {"t": "The Just World Hypothesis in Trading", "s": "The belief that the market is always 'fair'", "cards": [
  {"t": "What is the Just World Hypothesis?", "b": "<p>The <strong style=\"color:#00FF9D\">Just World Hypothesis</strong> is the tendency to believe the world is fundamentally fair — good deeds are followed by reward, bad ones by punishment.</p>"},
  {"t": "How does it appear mistakenly in trading?", "b": "<p>Many unconsciously believe that if they have <strong style=\"color:#00FF9D\">\"worked hard enough\" or \"deserve\"</strong> the profit, the market will somehow reward them \"fairly\" — while the market is completely indifferent to individual effort or \"deservingness\".</p>"},
  {"t": "Why is this belief dangerous?", "b": "<p>If you believe the market <strong style=\"color:#00FF9D\">has to be \"fair\"</strong> to you, after an unexpected loss you may tend to experience it as an \"injustice\" instead of accepting the market's natural, indifferent risks.</p>"},
  {"t": "How does accepting reality help?", "b": "<p>The market <strong style=\"color:#00FF9D\">doesn't \"owe\" you anything</strong> — neither profit nor \"fair\" treatment. Accepting this helps you handle losses more objectively, with less emotional hurt, as part of the normal process.</p>"}],
 "qs": [
  {"q": "What is the Just World Hypothesis?", "o": ["The market's actual, statistically measured efficiency", "The belief that the world is fundamentally fair and good is rewarded", "The market is always unpredictable", "Automatic enforcement of risk management rules"], "e": "The Just World Hypothesis is the belief that the world is fair and good deeds are followed by reward."},
  {"q": "How does it appear mistakenly in trading?", "o": ["The belief that deserved effort will be rewarded by the market", "The belief that the market rewards at random", "The market fairly rewards analysis", "It only appears in successful traders"], "e": "Many unconsciously believe 'deserved' effort will be rewarded, while the market is indifferent."},
  {"q": "Why is this belief dangerous?", "o": ["It guarantees success", "Because it always brings profit", "It always improves risk management", "We may experience a loss as an injustice"], "e": "We may experience a loss as an injustice instead of accepting the market's natural risks."},
  {"q": "What does the market not 'owe' you?", "o": ["Positive news", "Lower fees", "Neither profit nor fair treatment", "Faster execution"], "e": "The market owes you nothing, neither profit nor fair treatment for your effort."},
  {"q": "How does accepting reality help?", "o": ["It doesn't help, it is better to believe in fairness", "We can handle losses with less emotional hurt", "It reduces the analysis needed", "It always leads to immediate profit"], "e": "Accepting the market's indifference helps handle losses with less emotional hurt."}]},
"155": {"t": "Emotional Contagion in Trader Communities", "s": "When other people's panic or euphoria spreads to you", "cards": [
  {"t": "What is emotional contagion?", "b": "<p><strong style=\"color:#00FF9D\">Emotional contagion</strong> is the phenomenon where other people's emotional state (panic, euphoria, fear) unconsciously \"spreads\" to us, often without us consciously noticing the effect.</p>"},
  {"t": "How does it appear in trader communities (forums, chats)?", "b": "<p>If <strong style=\"color:#00FF9D\">everyone in a trader chat group panics</strong> during a sudden drop, you can easily \"catch\" that panic, even if your own analysis doesn't justify the reaction.</p>"},
  {"t": "Why is this dangerous for decision-making?", "b": "<p>Decisions made under emotional contagion <strong style=\"color:#00FF9D\">don't come from your own, objective analysis</strong> but from the group's mood — this is close to the herd mentality learned earlier, but focuses specifically on the mechanism of emotional transfer.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It can help to <strong style=\"color:#00FF9D\">consciously pause</strong> following trader communities during intense market moments and rely on your own pre-written plan, instead of being swept up in the group's emotional wave.</p>"}],
 "qs": [
  {"q": "What is emotional contagion?", "o": ["Objective measurement of market mood", "The spread of a physical illness", "Other people's emotional state unconsciously spreading to us", "A sentiment oscillator plotted under the chart"], "e": "Emotional contagion is the phenomenon where other people's emotional state unconsciously spreads to us."},
  {"q": "How does it appear in trader chat groups?", "o": ["It never happens in communities", "Group panic can spread, even without justification", "It only appears in profitable situations", "It always improves objective decisions"], "e": "If everyone in a chat group panics, that panic can easily spread, even if it isn't justified."},
  {"q": "How does it relate to herd mentality?", "o": ["There is no relationship between them", "Herd mentality never relates to emotions", "It is close to it, but focuses on the mechanism of emotional transfer", "It is always stronger than herd mentality"], "e": "Emotional contagion is close to herd mentality, but focuses specifically on emotional transfer."},
  {"q": "Why is such a decision dangerous?", "o": ["Because the group's decisions are always wrong", "It isn't dangerous, it always stays objective", "It comes not from your own analysis but from the group's mood", "It always leads to a better decision"], "e": "A decision made under emotional contagion comes from the group's mood, not from your own analysis."},
  {"q": "What helps protect against emotional contagion in trader communities?", "o": ["Never analysing your own feelings", "Always immediately following the group's mood", "A conscious break from following the communities", "Spending as much time in the group as possible during stressful moments"], "e": "It helps to consciously pause following communities in intense moments, relying on your own plan."}]},
"165": {"t": "Regret Aversion in Trading", "s": "The fear of regret that leads to bad decisions", "cards": [
  {"t": "What is regret aversion?", "b": "<p><strong style=\"color:#00FF9D\">Regret aversion</strong> is the tendency to make our decisions so as to minimise the chance of future REGRET — not necessarily based on the best expected outcome.</p>"},
  {"t": "How is this different from loss aversion?", "b": "<p>While loss aversion is about the fear of <strong style=\"color:#00FF9D\">actual financial loss</strong>, regret aversion is about EMOTIONAL regret — e.g. the feeling \"I should have known, yet I decided badly\".</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you closed a position too early and it then kept rising, because of the <strong style=\"color:#00FF9D\">fear of regret</strong> you may next time tend to hold a position too long, just to avoid the same feeling — which can lead to another mistake.</p>"},
  {"t": "Why is it dangerous if avoiding regret drives decisions?", "b": "<p>The fear of regret can lead to <strong style=\"color:#00FF9D\">inconsistent, emotion-driven decisions</strong> — once you close too early (fearing loss), another time you hold too long (fearing the regret of an early close), instead of following a consistent set of rules.</p>"}],
 "qs": [
  {"q": "What is regret aversion?", "o": ["The fear of financial loss", "Completely ignoring past regrets", "Striving to minimise future regret", "The broker's official publication of the daily economic calendar"], "e": "Regret aversion is striving to minimise future emotional regret, not deciding on the best expected outcome."},
  {"q": "How is this different from loss aversion?", "o": ["Loss aversion is an emotional fear, regret aversion a financial one", "Loss aversion is fear of financial loss, this is fear of emotional regret", "Loss aversion never occurs", "Regret aversion is always stronger"], "e": "Loss aversion is about the fear of financial loss; regret aversion is about the fear of emotional regret."},
  {"q": "How does it appear with a position closed early that kept rising?", "o": ["It always improves the future decision", "It always leads to an immediate early close", "Next time we close even earlier", "Next time you may hold a position too long to avoid regret"], "e": "Because of the fear of regret, next time we may tend to hold a position too long."},
  {"q": "Why can it lead to inconsistent decisions?", "o": ["We hold positions sometimes too briefly, sometimes too long, depending on the emotional outcome", "Because we always decide the same way, independent of emotions", "It doesn't, it always stays consistent", "Because everyone always makes the same mistake"], "e": "Avoiding regret can lead to inconsistent decisions, sometimes closing early, sometimes holding too long."},
  {"q": "What is the best defence against regret aversion?", "o": ["Following consistent rules laid down in advance", "Random decision-making", "Suppressing the feeling of regret", "Always following the most recent experience"], "e": "Following consistent rules laid down in advance is the best defence, regardless of the expected emotional outcome."}]},
"166": {"t": "Outcome Bias — Judging by the Result", "s": "When we consider a good decision bad just because it turned out badly", "cards": [
  {"t": "What is outcome bias?", "b": "<p><strong style=\"color:#00FF9D\">Outcome bias</strong> is the tendency to judge the QUALITY of a decision solely by its OUTCOME, rather than by the quality of the decision-making process.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>A <strong style=\"color:#00FF9D\">well-founded, disciplined trade</strong> that nevertheless closed at a loss for statistical reasons can easily seem a \"bad decision\" — while a reckless trade without rules that won by chance can seem a \"good decision\".</p>"},
  {"t": "Why is this dangerous for the learning process?", "b": "<p>If you evaluate your decisions solely by outcome, you can easily <strong style=\"color:#00FF9D\">draw the wrong lessons</strong> — reinforcing bad, rule-free behaviour (because it won once) and discarding a good, disciplined approach (because it lost once).</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It is worth evaluating every trade <strong style=\"color:#00FF9D\">by the decision-making PROCESS</strong> (did you follow your plan, was there a real setup, was risk management appropriate), NOT just by the end result — this helps you learn more objectively from your trading journal.</p>"}],
 "qs": [
  {"q": "What is outcome bias?", "o": ["Precisely calculating the statistical expected value", "Objectively evaluating the decision process", "Judging a decision solely by its outcome", "Automatically applying the daily loss limit"], "e": "Outcome bias is judging a decision's quality solely by its outcome, instead of the process."},
  {"q": "How does it appear with a good but losing trade?", "o": ["It may seem a bad decision just because of the loss", "We consider it a good decision, because the loss doesn't count", "We always evaluate it objectively", "We consider it the good decision it was"], "e": "A well-founded trade that closed at a loss can wrongly seem a 'bad decision' because of outcome bias."},
  {"q": "Why is this dangerous for learning?", "o": ["Because it always reinforces good decisions", "It always improves self-assessment", "It can reinforce bad behaviour and discard good behaviour", "It isn't dangerous, it always leads to the right lesson"], "e": "Outcome bias can lead to wrong lessons, because we judge decision quality by a random outcome."},
  {"q": "How is it worth evaluating a trade's quality?", "o": ["Only based on other people's opinions", "Randomly, without analysis", "By the decision-making process, looking at plan adherence", "Solely by the end result"], "e": "It is worth evaluating a trade by the decision-making process, not just by the end result."},
  {"q": "What is the relationship between the journal and outcome bias?", "o": ["The journal always reinforces the effect of outcome bias", "The journal can only record the end result", "The journal can objectively record the decision process", "There is no relationship at all"], "e": "The journal can help objectively record the decision process, separating it from the end result."}]},
"175": {"t": "Status Quo Bias in Trading", "s": "When doing nothing seems the safest choice", "cards": [
  {"t": "What is status quo bias?", "b": "<p><strong style=\"color:#00FF9D\">Status quo bias</strong> is the tendency to prefer maintaining the current state over change, even when the change would objectively be better.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If a strategy has <strong style=\"color:#00FF9D\">become \"familiar\" for a while</strong>, you may tend to cling to it even when the objective data (trading journal) shows it should be changed.</p>"},
  {"t": "Why is it hard to update an outdated trading plan?", "b": "<p>Because of status quo bias, <strong style=\"color:#00FF9D\">updating/modifying the plan can seem like extra work and risk</strong> — it is much more comfortable to follow the familiar routine, even if it is no longer optimal.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to build <strong style=\"color:#00FF9D\">regular, scheduled reviews</strong> into your routine (e.g. once a month objectively going through the journal and the plan) — this proactively counterbalances the natural tendency towards the status quo.</p>"}],
 "qs": [
  {"q": "What is status quo bias?", "o": ["The market's actual, measured level of liquidity", "A tendency to change things often", "Mandatory daily testing of the trading strategy", "A tendency to keep the current state, even if it is worse"], "e": "Status quo bias is the tendency to keep the current state, even when change would be better."},
  {"q": "How does it appear with a familiar strategy?", "o": ["We always change immediately if the data justifies it", "We may cling to it even if the data shows otherwise", "We often switch strategy", "It never affects the choice of strategy"], "e": "Because of status quo bias we may cling to the familiar strategy even if the data would justify a change."},
  {"q": "Why is it hard to update an outdated plan?", "o": ["Because it must be updated every day", "It can seem like extra work and risk compared to the familiar", "Because plans never become outdated", "It isn't hard, updating is always immediate"], "e": "Updating can seem like extra work and risk, while the familiar routine feels more comfortable."},
  {"q": "How can you protect yourself against status quo bias?", "o": ["By ignoring the journal", "By trying a new strategy every day", "With regular, scheduled reviews", "By never reviewing the strategy"], "e": "Scheduled, regular reviews counterbalance the tendency towards the status quo."},
  {"q": "Why is a scheduled review proactive?", "o": ["It always means an immediate strategy switch", "It is never needed", "It builds in the possibility of change in advance, without waiting for a crisis", "It isn't proactive, only reactive"], "e": "A scheduled review builds in the possibility of change in advance, without waiting for a crisis."}]},
"176": {"t": "The Framing Effect in Trading", "s": "The same fact, phrased differently — produces a different decision", "cards": [
  {"t": "What is the framing effect?", "b": "<p>The <strong style=\"color:#00FF9D\">framing effect</strong> describes how the same objective information, phrased in DIFFERENT WAYS, can lead to different decisions — even though the actual content is identical.</p>"},
  {"t": "A classic example in trading", "b": "<p>\"This strategy has a 70% win rate\" versus \"this strategy loses 30% of the time\" — <strong style=\"color:#00FF9D\">objectively the same information</strong>, yet the first phrasing can seem far more attractive.</p>"},
  {"t": "How can you use this consciously in your own analysis?", "b": "<p>When evaluating a strategy or setup, try to <strong style=\"color:#00FF9D\">phrase the same fact in several ways</strong> — if one framing seems more attractive than another, that may signal you are under the framing effect rather than deciding on the objective data.</p>"},
  {"t": "Why does this matter when you read other people's analysis?", "b": "<p>If someone presents an opportunity with <strong style=\"color:#00FF9D\">deliberately positive framing</strong> (e.g. only highlighting winning trades), it helps to consciously look for the alternative, more neutral phrasing before deciding.</p>"}],
 "qs": [
  {"q": "What is the framing effect?", "o": ["Precise, numerical measurement of daily volume", "The same info phrased differently produces a different decision", "The risk warning the broker must publish", "The effect of the chart's frame"], "e": "The framing effect means the same objective info, phrased differently, leads to a different decision."},
  {"q": "What is the classic example in trading?", "o": ["'70% win rate' vs 'loses 30% of the time'", "Comparing commissions", "'Always wins' vs 'never loses'", "Just changing the chart's colour"], "e": "'70% win rate' and 'loses 30% of the time' say the same thing, yet create different impressions."},
  {"q": "How can you use this awareness consciously?", "o": ["By accepting only one phrasing", "By phrasing the same fact in several ways", "By never thinking about phrasing", "By ignoring every statistic"], "e": "It helps to phrase the same fact in several ways, to see whether its attractiveness changes."},
  {"q": "Why does this matter when reading other people's analysis?", "o": ["Because other people's analysis never contains framing", "It helps recognise deliberate or unconscious positive framing", "It helps decide which analysis is more popular", "Because it only applies to ourselves"], "e": "It helps recognise when someone presents an opportunity with deliberately positive framing."},
  {"q": "What is the practical lesson?", "o": ["Never paying attention to phrasing", "Looking for the basic, raw data instead of the framing", "Always accepting the most positive phrasing", "The framing effect is not relevant"], "e": "It is worth looking for the basic, raw data, not just accepting a particular, possibly distorted framing."}]},
"185": {"t": "Base Rate Neglect in Trading", "s": "When an exciting story overrides dry statistics", "cards": [
  {"t": "What is base rate neglect?", "b": "<p><strong style=\"color:#00FF9D\">Base rate neglect</strong> is the tendency to overvalue a specific, vivid story/anecdote compared to the general, statistical base data (base rate).</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you hear a <strong style=\"color:#00FF9D\">specific, exciting story</strong> about someone who got rich on a single trade, it can easily override your sober knowledge that the statistical majority of day traders lose in the long run.</p>"},
  {"t": "Why is an anecdote psychologically stronger than statistics?", "b": "<p>The human brain <strong style=\"color:#00FF9D\">reacts more vividly to specific stories</strong> than to abstract numbers — a nameless \"70%\" statistic is far less memorable than a specific, detailed success story.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>When you hear a <strong style=\"color:#00FF9D\">convincing, specific success story</strong>, consciously ask: \"What is the general statistic/base rate compared to this? Is this story the rule or the exception?\"</p>"}],
 "qs": [
  {"q": "What is base rate neglect?", "o": ["Overweighting the statistical base frequency", "The minimum entry stake size set by the broker", "Always excessively and exclusively considering general statistics", "Overvaluing a specific anecdote compared to the statistical base"], "e": "Base rate neglect is overvaluing a specific, vivid anecdote compared to the statistical base data."},
  {"q": "How does base rate neglect appear in day trading?", "o": ["It never influences our trading decisions in any form", "It only appears in those who are currently losing", "We always rely exclusively on statistical data when deciding", "A success story can override the knowledge that most traders lose"], "e": "An exciting success story can override sober knowledge about day traders' statistical performance."},
  {"q": "Why is an anecdote stronger than statistics?", "o": ["Because statistical data is actually never reliable", "Because anecdotes are always objectively more accurate", "The brain reacts more vividly to specific stories than to abstract data", "It isn't stronger, statistics always stay far more memorable"], "e": "The human brain reacts more vividly to specific stories than to abstract, nameless statistical data."},
  {"q": "Which question helps recognise base rate neglect?", "o": ["'How exciting and gripping is this particular story?'", "'When exactly did this event happen?'", "'Who exactly told me this story?'", "'What is the general statistic compared to this story?'"], "e": "It helps to ask what the general statistic is compared to a specific story."},
  {"q": "Why is it dangerous to base a decision on a single success story?", "o": ["It may be a statistical exception, not the typical, expected result", "It isn't dangerous, it always gives a fully reliable basis", "Statistics are never relevant to any decision", "Every success story is necessarily and always false"], "e": "A success story may be a statistical exception, not the typical, expected result."}]},
"186": {"t": "The Curse of Knowledge in Trading", "s": "When we believe the market 'should know' what we know", "cards": [
  {"t": "What is the curse of knowledge?", "b": "<p>The <strong style=\"color:#00FF9D\">curse of knowledge</strong> is the bias where we find it hard to imagine what it would be like NOT to know something we already know — this can lead to distorted expectations about how others (or the market) \"should\" behave.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you <strong style=\"color:#00FF9D\">have spotted an \"obvious\" technical signal</strong>, you may easily think the market \"should\" move accordingly — forgetting that the market is the combined behaviour of masses of people and algorithms, not of a single \"logical\" participant.</p>"},
  {"t": "Why does this lead to disappointment and irrational reactions?", "b": "<p>If the market <strong style=\"color:#00FF9D\">doesn't move according to your \"logical\" analysis</strong>, you can easily become frustrated, as if the market were \"wrong\" — while really your model just didn't cover the full, complex reality.</p>"},
  {"t": "How does humility help against this?", "b": "<p>Accepting that <strong style=\"color:#00FF9D\">your own knowledge and analysis are only a partial picture</strong> of the market's full complexity helps avoid frustration and irrationally \"arguing\" with the market when it doesn't behave as expected.</p>"}],
 "qs": [
  {"q": "What is the curse of knowledge?", "o": ["The market's actual, objectively measured efficiency", "Mandatory written recording of the trading plan", "Finding it hard to imagine NOT knowing something we already know", "Having too little knowledge about a subject"], "e": "The curse of knowledge is the difficulty of imagining not knowing something we already know."},
  {"q": "How does the curse of knowledge appear in day trading?", "o": ["It never affects analysis", "We think the market reacts unpredictably to every signal", "We accept that the market is unpredictable", "We think the market 'should' move based on a signal"], "e": "We may think the market should move based on an 'obvious' signal, forgetting its complexity."},
  {"q": "Why can it lead to frustration?", "o": ["The market always moves as expected", "It always leads to calm acceptance", "We may become frustrated when the market doesn't move 'logically'", "It doesn't lead to any emotional reaction"], "e": "If the market doesn't move according to our own logic, we may get frustrated, although our model was incomplete."},
  {"q": "How does humility help against this?", "o": ["By accepting that our knowledge is only a partial picture of the complexity", "It doesn't help, you must always be certain", "It has nothing to do with market analysis", "It always weakens decisions"], "e": "Accepting that our knowledge is only a partial picture of the market's complexity reduces frustration."},
  {"q": "Why isn't the market 'wrong' if it doesn't move in the expected direction?", "o": ["Because every signal is always accurate", "Because the market never moves on signals", "The market is actually always wrong", "It is the combined behaviour of many participants, not of one 'logical' analyst"], "e": "The market is the combined behaviour of many different participants, so our model may have been incomplete; the market isn't 'wrong'."}]},
"195": {"t": "The Illusion of Validity", "s": "When our confidence is out of proportion to our actual accuracy", "cards": [
  {"t": "What is the illusion of validity?", "b": "<p>The <strong style=\"color:#00FF9D\">illusion of validity</strong> is the phenomenon where our subjective confidence in a prediction does NOT correlate with its actual accuracy — we feel confident regardless of how reliable our analysis really is.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If a setup <strong style=\"color:#00FF9D\">\"ticks every box\"</strong> (several indicators line up, a clean chart pattern), you may feel extremely confident — while the actual statistical win rate may nevertheless be the same as for a less \"perfect-looking\" setup.</p>"},
  {"t": "Why is this especially deceptive with consistent patterns?", "b": "<p>The <strong style=\"color:#00FF9D\">more consistent and \"beautiful\" a pattern</strong>, the more confident we feel about it — but a pattern's visual \"beauty\" doesn't guarantee real, statistical reliability.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>The best defence is <strong style=\"color:#00FF9D\">objective, backtesting-based data</strong> — don't let the subjective feeling \"this looks like a really clean setup\" override what your actual, measured statistics show about a given setup type.</p>"}],
 "qs": [
  {"q": "What is the illusion of validity?", "o": ["Subjective confidence doesn't correlate with real accuracy", "The mathematical relationship between daily volume and spread", "Confidence always reflects accuracy", "Objective, precise measurement of backtesting results"], "e": "The illusion of validity means our confidence doesn't correlate with actual predictive accuracy."},
  {"q": "How does it appear with a 'perfect-looking' setup?", "o": ["It triggers caution and a smaller position size", "It creates confidence, regardless of the real statistics", "It always accurately reflects the real quality", "It only appears with losing setups"], "e": "A setup that 'ticks every box' creates confidence, regardless of its actual statistical reliability."},
  {"q": "Why is it deceptive with 'beautiful' patterns?", "o": ["Because only ugly patterns are reliable", "Visual beauty doesn't guarantee real reliability", "Because beautiful patterns never occur", "It isn't deceptive, beautiful is always more reliable"], "e": "A pattern's visual beauty doesn't guarantee its real, statistical reliability."},
  {"q": "What is the best defence against the illusion of validity?", "o": ["Never analysing any setup", "Using objective, backtesting-based data", "Maximum stake on the 'most beautiful' setups", "Relying on the subjective feeling"], "e": "Using objective, backtesting-based data helps avoid a false sense of security."},
  {"q": "Why is it important to distinguish confidence from accuracy?", "o": ["It isn't important, the two are always the same", "Confidence always guarantees success", "Confidence can lead to a false sense of security and bad decisions", "Accuracy can never be measured"], "e": "A false sense of security can lead to bad risk management decisions, e.g. an excessive stake size."}]},
"196": {"t": "Choice Overload — Paralysed by Too Many Options", "s": "When choosing between many strategies/instruments paralyses you", "cards": [
  {"t": "What is choice overload?", "b": "<p><strong style=\"color:#00FF9D\">Choice overload</strong> is the phenomenon where TOO MANY available options (strategies, instruments, indicators) actually make decision-making harder, not easier.</p>"},
  {"t": "How is this different from analysis paralysis?", "b": "<p>While analysis paralysis is about over-analysis <strong style=\"color:#00FF9D\">WITHIN a single decision</strong>, choice overload is more about having to choose among TOO MANY competing OPTIONS (e.g. which strategy to learn, which instrument to specialise in).</p>"},
  {"t": "How does it appear in beginner day traders?", "b": "<p>A beginner who meets <strong style=\"color:#00FF9D\">dozens of strategies, indicators and asset classes</strong> at once can easily be paralysed by the choice — never going deep enough into any of them, because they keep wavering between new options.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">consciously narrow your focus</strong> — choose one or two strategies and asset classes and commit to going deep into them before considering new options, instead of constantly \"shopping around\".</p>"}],
 "qs": [
  {"q": "What is choice overload?", "o": ["Too few available options", "The broker's daily newsletter", "A kind of risk management rule", "Too many options, which make the decision harder"], "e": "Choice overload is the phenomenon where too many available options make the decision harder, not easier."},
  {"q": "How is this different from analysis paralysis?", "o": ["Choice overload is always more severe", "That one is paralysis within a decision, this is paralysis among competing options", "Analysis paralysis is among competing options, this is within one decision", "Analysis paralysis never occurs"], "e": "Analysis paralysis is over-analysis within one decision; choice overload is the difficulty of choosing among competing options."},
  {"q": "How does it appear in beginners?", "o": ["They keep wavering between new options, never going deep into any", "It always improves learning", "It never affects beginners", "They choose immediately and confidently"], "e": "Wavering between many options, the beginner never goes deep into any, gaining only superficial knowledge."},
  {"q": "How can you protect against this?", "o": ["By narrowing focus to one or two strategies", "By switching strategy daily", "By never choosing anything", "By trying as many strategies at once as possible"], "e": "It helps to consciously narrow the focus to one or two strategies/instruments and commit to going deep into them."},
  {"q": "Why does constant switching lead to superficial knowledge?", "o": ["Because it always speeds up learning", "Because the more we try, the deeper the knowledge becomes", "It doesn't, it always gives deep knowledge", "It prevents us from gaining real expertise in any of them"], "e": "Constantly switching options prevents gaining real, deep expertise in any area."}]}
});

// ---- Part 4: lessons 205–255 ----
Object.assign(window.LESSONS_EN, {
"205": {"t": "Cognitive Dissonance in Trading", "s": "When we hold two contradicting beliefs at the same time", "cards": [
  {"t": "What is cognitive dissonance?", "b": "<p><strong style=\"color:#00FF9D\">Cognitive dissonance</strong> is the unpleasant psychological tension we feel when we hold two mutually contradicting beliefs or convictions at the same time.</p>"},
  {"t": "How does it appear with a losing position?", "b": "<p>If your position is losing but you <strong style=\"color:#00FF9D\">consider yourself a \"good trader\"</strong>, these two thoughts contradict each other — to resolve the dissonance you may tend to rationalise the loss (\"it's only temporary\", \"the market is manipulated\") instead of facing it objectively.</p>"},
  {"t": "Why is this dangerous for the learning process?", "b": "<p>Instead of accepting and learning from the mistake, dissonance-reducing <strong style=\"color:#00FF9D\">rationalisation prevents objective self-assessment</strong> — similar to the self-serving bias learned earlier, but here the emphasis is on holding two contradicting beliefs together.</p>"},
  {"t": "How can you resolve the dissonance in a healthy way?", "b": "<p>Instead of defending your belief (\"I'm a good trader\") against reality, it is healthier to <strong style=\"color:#00FF9D\">refine the belief</strong>: \"I'm a good trader WHO LEARNS FROM THIS MISTAKE\" — this resolves the tension without distorting your perception of reality.</p>"}],
 "qs": [
  {"q": "What is cognitive dissonance?", "o": ["The annual maintenance cost set by the broker", "An indicator that measures momentum numerically", "Always agreeing with our own decisions without questioning them", "The tension caused by holding two contradicting beliefs at once"], "e": "Cognitive dissonance is the tension caused by holding two contradicting beliefs at the same time."},
  {"q": "How does cognitive dissonance appear with a losing position?", "o": ["We always accept the situation immediately and objectively", "We may rationalise the loss to resolve the contradiction", "It always automatically improves the quality of the next decision", "It never affects our self-assessment in any way"], "e": "We may rationalise the loss to resolve the contradiction between 'I'm a good trader' and 'I'm losing'."},
  {"q": "Why is rationalisation dangerous for learning?", "o": ["It always leads us to faster, more efficient progress", "It can prevent objective self-assessment and learning", "Only a theoretical concern, irrelevant in practice", "It isn't dangerous, it always helps rapid progress"], "e": "Rationalisation can prevent objective self-assessment, blocking learning from mistakes."},
  {"q": "How can it be resolved in a healthy way?", "o": ["By refining the belief, acknowledging learning from the mistake", "By ignoring the loss completely, forever", "By an immediate, ill-considered change of strategy in every case", "By completely denying reality under all circumstances"], "e": "Refining the belief ('I'm a good trader who learns') resolves the tension without distortion."},
  {"q": "How is it similar to self-serving bias?", "o": ["Both can distort reality to protect our self-image", "Self-serving bias actually never happens to anyone", "Cognitive dissonance always has a much stronger effect", "There is no meaningful similarity between the two"], "e": "Both phenomena can distort reality in order to protect our self-image."}]},
"206": {"t": "Sunk Time — The Learning Investment Trap", "s": "When abandoning a strategy makes the learning feel 'wasted'", "cards": [
  {"t": "How is this different from the financial sunk cost learned earlier?", "b": "<p>The sunk cost fallacy learned earlier was typically about MONEY — this variant focuses on when you have put a lot of <strong style=\"color:#00FF9D\">TIME and energy into learning a strategy or method</strong>, which makes it harder to let go, even if it doesn't work.</p>"},
  {"t": "How does this appear in practice?", "b": "<p>\"I spent months learning Elliott Wave theory, <strong style=\"color:#00FF9D\">I can't stop now</strong>\" — even if your own objective backtesting results show the method isn't bringing you the expected results.</p>"},
  {"t": "Why is this bias especially strong with complex methods?", "b": "<p>The <strong style=\"color:#00FF9D\">more complicated and time-consuming</strong> a method was to master, the stronger the attachment to it can be — dropping simpler techniques hurts less than dropping a long, complex learning process.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>Remind yourself: <strong style=\"color:#00FF9D\">the learning process itself wasn't useless</strong>, even if the specific method doesn't work out — the knowledge gained (e.g. chart-reading skill) can be transferred to other, perhaps better-working approaches.</p>"}],
 "qs": [
  {"q": "How does the sunk cost of learning time differ from the financial sunk cost fallacy?", "o": ["The sunk cost of learning time always has a stronger effect in every situation", "The financial sunk cost fallacy never occurs in trading practice", "There is no difference, the two are practically the same phenomenon", "Here the learning invested in time, not money, makes dropping a method harder"], "e": "The sunk cost of learning time focuses on how a lot of time spent learning makes it harder to drop a method that doesn't work."},
  {"q": "How does this appear in practice?", "o": ["It never affects our decisions, it stays a completely neutral factor", "I spent a lot of time learning it, I can't stop, even if it doesn't work", "Every imperfect method must always be dropped immediately, without exception", "It was easy to learn, so I drop it easily and quickly, without experience"], "e": "If someone has spent a lot of time learning a method, it is harder to let go, even if objective results don't support it."},
  {"q": "Why is this bias especially strong with complex methods?", "o": ["The more complicated the learning was, the stronger the attachment can be", "Because simple methods never cause a sunk cost effect in traders", "It isn't stronger, it affects every method equally, regardless of complexity", "Because complex methods always work better than simpler ones"], "e": "The more complicated and time-consuming a method was to master, the stronger the attachment to it can be."},
  {"q": "How can you protect yourself against the sunk cost of learning time?", "o": ["By keeping every method forever, regardless of real performance", "By never learning new methods for fear of future disappointment", "By considering the learning time wasted if the method doesn't work out", "By reminding yourself that the knowledge gained transfers to other approaches"], "e": "It helps to remind ourselves that the knowledge and skills gained can be transferred to other approaches too."},
  {"q": "What is the main message of this lesson?", "o": ["Every method learned must be kept forever, regardless of performance", "Learning time never affects decision-making, it stays completely neutral", "Time invested in learning is no reason to keep forcing a method that doesn't work", "You should never learn a new method, because the time is always completely wasted"], "e": "The main message is that time invested in learning is not, by itself, a reason to force a method that objectively doesn't work."}]},
"214": {"t": "Illusory Correlation in Trading", "s": "When we see a connection where there is none", "cards": [
  {"t": "What is illusory correlation?", "b": "<p><strong style=\"color:#00FF9D\">Illusory correlation</strong> is the bias where we think we have discovered a connection between two events/variables, although they are actually not related statistically, or only by chance.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you <strong style=\"color:#00FF9D\">experience a coincidence</strong> a few times (e.g. \"whenever I wear a blue T-shirt, I win\"), you can easily assume a false causal link, although it was purely a random coincidence, not a real relationship.</p>"},
  {"t": "Why is this dangerous when evaluating indicator combinations?", "b": "<p>If by chance you <strong style=\"color:#00FF9D\">see two actually independent signals together</strong> a few times (e.g. a particular candle pattern and a particular RSI value), you may believe they give a strong, reliable signal together — although this is just chance due to the small sample size.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>The best defence is <strong style=\"color:#00FF9D\">systematic backtesting with a large sample size</strong> — if a supposed relationship rests on just a few observations, it can easily be an illusory correlation, not a real, statistically reliable pattern.</p>"}],
 "qs": [
  {"q": "What is illusory correlation?", "o": ["A real, thoroughly proven statistical relationship between two variables", "An indicator that precisely measures market volatility", "Perceiving a false connection between two actually independent events", "The fixed per-transaction fee charged by the broker"], "e": "Illusory correlation is perceiving a false connection between two events that are actually unrelated."},
  {"q": "How does illusory correlation appear in day trading?", "o": ["It only occurs in traders who have been active for a long time", "It never affects our trading decisions in any way", "We always find objective, statistically founded patterns", "Based on a few random coincidences we assume a false causal link"], "e": "Based on a few random coincidences we may assume a false causal link."},
  {"q": "Why is it dangerous when evaluating indicator combinations?", "o": ["Because in theory indicators can never be combined with each other", "It isn't dangerous, it always leads us to correct conclusions", "Based on a few random coincidences we may wrongly believe a weak signal is strong", "Because in reality only a single indicator exists in the market"], "e": "Based on a few random coincidences we may wrongly believe an actually weak combination is strong and reliable."},
  {"q": "What is the best defence against illusory correlation?", "o": ["Building a strategy on it immediately after a few observations", "Always believing and following our first impression uncritically", "Never thoroughly testing any recognised pattern", "Carrying out thorough, systematic backtesting with a large sample size"], "e": "Systematic backtesting with a large sample size helps distinguish a real pattern from chance."},
  {"q": "Why does it occur more often with a small sample size?", "o": ["It doesn't occur more often, sample size doesn't matter at all", "Because a large sample always, without exception, gives wrong results", "Because a small sample is always objectively more accurate than a large one", "Random coincidences can have a disproportionately large effect on a small sample"], "e": "With a small sample size, random coincidences can have a disproportionately large effect on the perceived pattern."}]},
"215": {"t": "Feedback Overload", "s": "When too many contradicting opinions paralyse you", "cards": [
  {"t": "What is feedback overload?", "b": "<p><strong style=\"color:#00FF9D\">Feedback overload</strong> occurs when we get feedback from too many sources (forums, mentors, social media) that often CONTRADICTS itself, which paralyses decision-making.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you follow <strong style=\"color:#00FF9D\">several \"experts'\" opinions</strong> on the same asset at once and they contradict each other, you can easily lose confidence in your own, previously formed analysis.</p>"},
  {"t": "How is this different from the analysis paralysis learned earlier?", "b": "<p>While analysis paralysis comes from <strong style=\"color:#00FF9D\">your own excessive analysis</strong>, feedback overload comes specifically from a mass of EXTERNAL, varied and contradicting opinions — the source differs, though the end result (paralysis) is similar.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">consciously limit</strong> how many external sources you actively follow, and rely primarily on your own tested analysis and plan, treating outside opinions only as a supplementary input, not a deciding factor.</p>"}],
 "qs": [
  {"q": "What is feedback overload?", "o": ["Too little feedback, causing uncertainty", "Too much contradicting feedback, which paralyses the decision", "A shortage of available information", "A kind of technical alert"], "e": "Feedback overload is decision paralysis caused by too much mutually contradicting feedback."},
  {"q": "How does this show up in day trading?", "o": ["It only happens to the broker's employees", "Several contradicting opinions make you unsure of your own analysis", "It never affects traders", "We always rely on a single, clear source"], "e": "Following several contradicting opinions at once can make you unsure of your own, previously formed analysis."},
  {"q": "What separates feedback overload from analysis paralysis?", "o": ["In no way, the two are identical", "It is caused by your own excessive analysis, not outside opinions", "It is caused by many outside opinions, not by your own excessive analysis", "Feedback overload is only a theoretical concept"], "e": "Analysis paralysis comes from your own excessive analysis; feedback overload from external, contradicting opinions."},
  {"q": "What helps protect against feedback overload?", "o": ["Ignoring the journal completely", "A limited set of sources and relying on your own plan", "Following as many sources at once as possible", "Blindly following the last opinion you heard"], "e": "It helps to limit the external sources you follow and rely primarily on your own tested plan."},
  {"q": "Why does relying on your own analysis give stability?", "o": ["Because it legally excludes other people's opinions", "It gives a consistent basis that outside noise finds harder to shake", "It gives no stability at all", "Because your own analysis is always flawless"], "e": "Relying on your own consistent analysis gives a stable basis that external, contradicting noise finds harder to shake."}]},
"223": {"t": "Impostor Syndrome in Trading", "s": "When you are successful but still feel like a fraud", "cards": [
  {"t": "What is impostor syndrome?", "b": "<p><strong style=\"color:#00FF9D\">Impostor syndrome</strong> is the feeling that despite our successes we are \"frauds\" — as if good results were due only to luck, not real ability.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>A trader who is <strong style=\"color:#00FF9D\">consistently profitable over the long term</strong> may still constantly feel that they are \"just lucky\" and could be \"exposed\" at any time — this can lead to irrational excessive caution or self-sabotage.</p>"},
  {"t": "How is this different from the Dunning-Kruger effect?", "b": "<p>While the Dunning-Kruger effect describes <strong style=\"color:#00FF9D\">an actual lack of competence</strong> and the overconfidence attached to it, impostor syndrome is exactly the OPPOSITE — unjustified lack of confidence despite REAL competence.</p>"},
  {"t": "How can you handle it in a healthy way?", "b": "<p>It helps to <strong style=\"color:#00FF9D\">rely on objective data (trading journal, expectancy)</strong> for self-assessment, not on the subjective feeling — if the data consistently shows good performance, the data, not the feeling, is the more objective reality.</p>"}],
 "qs": [
  {"q": "What is impostor syndrome?", "o": ["Overconfidence without competence", "Feeling like a fraud despite successes", "Excessive self-assurance after successes", "Becoming cocky once the wins pile up"], "e": "Impostor syndrome is the feeling that despite our successes we are frauds, as if we were just lucky."},
  {"q": "How does it appear in a consistently profitable trader?", "o": ["They feel excessive confidence", "It automatically improves further performance", "It always makes them confident", "They may constantly feel they are just lucky"], "e": "Even a consistently profitable trader may constantly feel they are just lucky, which can lead to caution."},
  {"q": "How is it different from the Dunning-Kruger effect?", "o": ["In no way, it is the same", "Impostor syndrome is always more severe", "Only a theoretical concept, it never occurs", "Dunning-Kruger is overconfidence despite lack of competence, this is the opposite"], "e": "Dunning-Kruger is overconfidence despite lack of competence; impostor syndrome is its opposite."},
  {"q": "How can it be handled in a healthy way?", "o": ["By stopping trading immediately", "By relying on the subjective feeling", "By relying on objective data and the journal", "Exclusively by asking other people's opinions"], "e": "It helps to rely on objective data (journal, expectancy) for self-assessment, not on the subjective feeling."},
  {"q": "Why is data more objective than feeling?", "o": ["Because feeling is never relevant to any decision", "Because data never lies in any context", "It isn't more objective, feeling is always more accurate", "Consistently good data shows reality, not the momentary doubt"], "e": "If the data consistently shows good performance, that is a more objective reality than the subjective feeling of being a fraud."}]},
"224": {"t": "Motivated Reasoning in Trading", "s": "When we actively look for arguments for what we want to believe", "cards": [
  {"t": "What is motivated reasoning?", "b": "<p><strong style=\"color:#00FF9D\">Motivated reasoning</strong> is the process where we unconsciously and ACTIVELY seek and evaluate information so that it supports what we already WANT to believe — not necessarily what is objectively true.</p>"},
  {"t": "How is this broader than the confirmation bias learned earlier?", "b": "<p>While confirmation bias is more <strong style=\"color:#00FF9D\">passive</strong> (we more readily believe confirming info), motivated reasoning is a MORE ACTIVE process — consciously or unconsciously we SEARCH for arguments for a desired conclusion.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you <strong style=\"color:#00FF9D\">want your position to be profitable</strong> (e.g. because you have been in it a long time), you may unconsciously do \"research\" to find an indicator or news item that supports your decision to continue.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to consciously ask: <strong style=\"color:#00FF9D\">\"What am I looking for right now — the truth, or confirmation of a decision already made?\"</strong> — this distinction can help you notice when you are slipping into motivated reasoning.</p>"}],
 "qs": [
  {"q": "What is motivated reasoning?", "o": ["Mandatory daily keeping of the trading journal", "Actively searching for arguments for a desired conclusion", "Objective, unbiased data collection before every decision", "A passive tendency to believe confirming info"], "e": "Motivated reasoning actively searches for arguments to support a desired conclusion."},
  {"q": "How is this broader than confirmation bias?", "o": ["There is no difference between them", "Confirmation bias is more passive, this actively searches for arguments", "Confirmation bias never occurs", "This always has a weaker effect"], "e": "Confirmation bias is more passive; motivated reasoning actively searches for arguments."},
  {"q": "How does motivated reasoning appear with an open position?", "o": ["We analyse the position objectively", "We do 'research' to support continuing", "We deliberately hunt for reasons to exit", "We deliberately seek out the counterarguments"], "e": "If we want a position to be profitable, we may unconsciously look for supporting info."},
  {"q": "Which question helps recognise motivated reasoning?", "o": ["'Am I looking for the truth, or confirmation of a decision?'", "'How much money have I already put into this?'", "'Who else is trading this?'", "'How long has this position been open?'"], "e": "It helps to ask whether we are looking for the truth or just confirmation of a decision already made."},
  {"q": "Why is it hard to recognise motivated reasoning in ourselves?", "o": ["It always comes with clear signs", "It only happens to others", "It works unconsciously; we don't realise we are searching selectively", "Because it is always a conscious, deliberate process"], "e": "It works unconsciously; we often don't realise we are searching for information selectively."}]},
"230": {"t": "Loss Chasing", "s": "The specific behaviour that breaks many trading careers", "cards": [
  {"t": "What is loss chasing?", "b": "<p><strong style=\"color:#00FF9D\">Loss chasing</strong> is the specific behaviour where, after a loss, we IMMEDIATELY and without consideration open a new, often bigger position to \"win back\" the money lost.</p>"},
  {"t": "How does this relate to the concepts learned earlier?", "b": "<p>Loss chasing is the practical, concrete manifestation of <strong style=\"color:#00FF9D\">trading tilt, the gambler's fallacy and escalation of commitment</strong> — those are the theoretical concepts, loss chasing is the actual, observable action.</p>"},
  {"t": "Why is it so dangerous statistically?", "b": "<p>Decisions made while loss chasing are <strong style=\"color:#00FF9D\">unplanned, often with bigger stakes than usual</strong> — statistically this is one of the most common paths to quickly losing the whole account, because a single bad day can escalate into a catastrophe.</p>"},
  {"t": "What is the only defence that works in practice?", "b": "<p>The most effective defence is a <strong style=\"color:#00FF9D\">rule set in stone</strong>: after a certain number of consecutive losses (e.g. 2–3), a MANDATORY break before opening any new position — this rule is non-negotiable, no matter how sure you feel about \"winning it back\".</p>"}],
 "qs": [
  {"q": "What is loss chasing?", "o": ["Immediately opening a bigger stake after a loss", "Thorough analysis of the trading journal afterwards", "Deliberately setting the daily limit in advance", "Calm, planned trading after a loss"], "e": "Loss chasing is immediately opening an ill-considered, often bigger position after a loss."},
  {"q": "Which concepts does it relate to?", "o": ["Only the broker's model", "Trading tilt, the gambler's fallacy and escalation of commitment", "Only the daily calendar", "Only Fibonacci"], "e": "Loss chasing is the practical manifestation of tilt, the gambler's fallacy and escalation of commitment."},
  {"q": "Why is it dangerous statistically?", "o": ["It guarantees winning it back", "Because chasing always shrinks the stake size", "It isn't dangerous, it improves the result", "Unplanned, with bigger stakes, it is the path to fast capital loss"], "e": "The unplanned, bigger stakes of loss chasing are one of the most common paths to quickly losing the account."},
  {"q": "What is the most effective defence?", "o": ["A rule set in stone: a break after a certain number of losses", "Trading again as fast as possible", "More trades to win back the losses", "Always doubling the stake after a loss"], "e": "A rule set in stone (e.g. a mandatory break after 2–3 losses) is the most effective defence."},
  {"q": "Why must the rule be non-negotiable?", "o": ["Because rules never work", "It doesn't need to be, it can always be overridden", "The temptation is strongest exactly when we feel surest", "Because non-negotiability worsens the result"], "e": "The temptation is strongest exactly at the moment of loss chasing, which is why the rule must be firm."}]},
"234": {"t": "Case Study: Handling a Bad Day", "s": "When every trade loses and discipline matters most", "cards": [
  {"t": "The situation: 3 losing trades in a row", "b": "<p>Bence loses three consecutive trades in the morning — each based on a good setup, but the market was choppy and unpredictable. <strong style=\"color:#00FF9D\">He feels the pressure</strong> to \"get the money back\".</p>"},
  {"t": "The decision point: what would tilt do, and what does Bence do?", "b": "<p><strong style=\"color:#00FF9D\">Trading tilt</strong> would dictate hitting back immediately with bigger stakes. Instead, Bence pulls out his pre-written rule: <strong style=\"color:#00FF9D\">after 3 losing trades, a mandatory 30-minute break</strong>.</p>"},
  {"t": "During the break: an objective, not emotional, review", "b": "<p>During the break Bence <strong style=\"color:#00FF9D\">doesn't dwell on his feelings</strong>, but goes through his journal — was the market choppy (a normal, statistical losing streak), or did he make some systematic mistake?</p>"},
  {"t": "The result: disciplined continuation or stopping", "b": "<p>Since the market was objectively choppy (low ADX, many false signals for everyone), Bence decides to <strong style=\"color:#00FF9D\">continue with a reduced stake size</strong>, according to the stake-reduction rule learned earlier — he doesn't give up the day completely, but doesn't force normal size either.</p>"}],
 "qs": [
  {"q": "What would trading tilt dictate in Bence's situation?", "o": ["Stopping trading completely and for good, as a drastic decision", "Hitting back immediately with bigger stakes", "An immediate, calm break, which would contradict the essence of tilt", "Changing the strategy immediately, quickly and without analysis"], "e": "Trading tilt would dictate trying to hit back immediately with bigger stakes."},
  {"q": "Which pre-written rule does Bence apply instead of tilt?", "o": ["He immediately looks for a new broker, as if that would solve the root problem", "He never stops, whatever happens while trading, continuously", "He immediately doubles the stake to win back the loss faster", "He takes a mandatory 30-minute break after 3 losing trades"], "e": "Bence applies a pre-written rule: a mandatory 30-minute break after 3 losing trades."},
  {"q": "What does Bence objectively examine during the break?", "o": ["He immediately looks for a new strategy online, switching quickly without analysis", "He only analyses his feelings, taking no other objective data into account", "Nothing, he just rests without thinking, avoiding all analysis", "He goes through his journal to see whether the market was choppy or he made a mistake"], "e": "During the break Bence examines the reasons for the losses objectively, based on his journal."},
  {"q": "What decision does Bence make after the objective review?", "o": ["He gives up trading immediately and for good, as a drastic final decision", "He doubles the stake to win back the lost money quickly", "He continues with a reduced stake size, according to the rule learned earlier", "He returns to normal stake size immediately, continuing without change"], "e": "Bence continues with a reduced stake size, according to the stake-reduction rule learned earlier."},
  {"q": "What is the lesson of the case study about handling a bad day?", "o": ["Pre-written rules and an objective review help resist tilt", "You must always give up trading immediately after a losing streak", "After a loss you must always open a bigger stake immediately", "The trading journal is useless on a bad day, another tool must be used"], "e": "Pre-written, mechanical rules and an objective review help resist the effect of tilt."}]},
"236": {"t": "Case Study: Handling FOMO in a Live Market", "s": "When a fast-moving asset tempts you to jump in hastily", "cards": [
  {"t": "The situation: a sudden, fast move", "b": "<p>An asset outside Dávid's watchlist suddenly rises 8% in minutes. In his trader chat group <strong style=\"color:#00FF9D\">everyone is talking about it</strong>, and Dávid feels he must get in immediately so as not to miss out.</p>"},
  {"t": "Recognising FOMO", "b": "<p>Dávid pauses for a moment and recognises: this is a textbook example of the <strong style=\"color:#00FF9D\">FOMO and herd mentality</strong> learned earlier — he has no analysis of his own prepared on this asset, he would just be following the crowd's excitement.</p>"},
  {"t": "The decision: staying out, not rushing", "b": "<p>Since the asset is <strong style=\"color:#00FF9D\">not on his own watchlist</strong> and a significant part of the move has already happened, Dávid decides to stay out — knowing that late entrants often get in right near the top.</p>"},
  {"t": "The result and the lesson", "b": "<p>In the next hour the asset <strong style=\"color:#00FF9D\">falls back by half of the move</strong>. Dávid writes in his journal: \"I stayed out of a FOMO trap — discipline is sometimes when you DON'T trade.\"</p>"}],
 "qs": [
  {"q": "Which phenomena learned earlier does Dávid's situation exemplify?", "o": ["Only the daily economic calendar, which concerns a fundamentally different topic", "Only the broker's execution model, which also belongs to a different area", "FOMO and herd mentality", "Only the Kelly Criterion, which is exclusively about position sizing"], "e": "Dávid's situation is a textbook example of FOMO and herd mentality, where the crowd's excitement would drive the decision."},
  {"q": "Why does it matter that Dávid has no analysis of his own on the asset?", "o": ["A hasty entry without analysis results in a worse risk/reward ratio", "It does not matter, following the crowd's opinion is enough for the decision", "Because analysis is always unnecessary in fast moves, it would waste time", "Because the crowd's analysis is always more accurate than individual analysis"], "e": "The lack of prior analysis means the entry would rest solely on the crowd's mood."},
  {"q": "Why does Dávid decide to stay out?", "o": ["The asset isn't on his watchlist, and a significant part of the move has already happened", "Because the broker forbade trading, legally restricting the decision", "Because the market was closed then, so entry would have been technically impossible", "Because you must always stay out of every fast move, without exception"], "e": "Dávid stays out because the asset isn't on his watchlist and a significant part of the move has already played out."},
  {"q": "What happens to the asset's price in the next hour?", "o": ["Nothing changes, the price stays stable at the top for the rest of the day", "It falls to zero immediately, causing extreme losses for every investor", "It keeps rising without limit, justifying the usefulness of an early entry", "It falls back by half of the move"], "e": "The asset's price falls back by half of the move, confirming the bad timing of a FOMO-based entry."},
  {"q": "What is the lesson's main takeaway about discipline?", "o": ["Discipline always means seizing every opportunity quickly", "Discipline has nothing to do with staying out, it only relates to active trading", "Discipline only applies to position sizing, it doesn't extend to other decisions", "Discipline sometimes means consciously not trading an opportunity"], "e": "Discipline sometimes shows precisely in consciously staying out of a tempting, unanalysed opportunity."}]},
"241": {"t": "Case Study: Overconfidence After a Winning Streak", "s": "When five consecutive wins are more dangerous than a defeat", "cards": [
  {"t": "The situation: five consecutive winning trades", "b": "<p>Anna wins five consecutive trades within a week. She feels <strong style=\"color:#00FF9D\">more and more confident</strong> and starts to think she has \"cracked\" the market.</p>"},
  {"t": "The dangerous thought: the rules are now 'unnecessary'", "b": "<p>Anna starts <strong style=\"color:#00FF9D\">questioning her own risk management rules</strong> — \"if it has gone this well so far, why shouldn't I open a bigger stake?\" This is a classic sign of the overconfidence and recency bias learned earlier.</p>"},
  {"t": "The decision point: the journal and objectivity", "b": "<p>Instead of immediately increasing her stake, Anna <strong style=\"color:#00FF9D\">looks at her long-term journal</strong> — the data from the last 6 months shows these five winning trades were a statistically normal, good streak, not proof of a \"cracked\" system.</p>"},
  {"t": "The result: disciplined continuation", "b": "<p>Anna <strong style=\"color:#00FF9D\">keeps her original position sizing rules</strong>, knowing that both winning and losing streaks are part of normal statistical fluctuation, not a reason to override the rules.</p>"}],
 "qs": [
  {"q": "Which biases learned earlier does Anna's behaviour show signs of?", "o": ["Only ignoring the daily economic calendar, which is a different topic", "Only loss aversion, which would mean a different psychological pattern", "Only misunderstanding the Kelly Criterion, which would be more of a maths problem", "Overconfidence and recency bias"], "e": "Anna's behaviour shows the classic signs of overconfidence and recency bias."},
  {"q": "Which dangerous thought starts to occupy Anna?", "o": ["That she should stop trading immediately, as a drastic decision", "That her rules are now 'unnecessary' and she could open a bigger stake", "That she should switch broker, citing technical reasons", "That she should reduce her stake size in the name of caution"], "e": "Under the influence of the winning streak Anna starts questioning her own risk management rules."},
  {"q": "What does Anna do instead of immediately increasing her stake?", "o": ["She looks at her long-term journal, seeking an objective perspective", "She believes she really has cracked the market, carrying on confidently", "She immediately doubles the stake without thinking, to exploit the momentum", "She stops trading completely, as a drastic and excessive reaction"], "e": "Anna looks at her long-term journal to get an objective perspective on the situation."},
  {"q": "What does Anna's long-term journal show about the five winning trades?", "o": ["That it was a statistically normal, good streak", "That it was a never-before-seen, unique performance in her trading career", "That she must increase her stake size immediately, justifying her confidence", "That her previous rules were completely wrong and must be overridden"], "e": "The journal shows the five winning trades were a statistically normal, good streak in the context of her overall performance."},
  {"q": "What is the lesson of the case of overconfidence after a winning streak?", "o": ["The longer a winning streak lasts, the surer it is to continue", "Both winning and losing streaks are part of normal statistical fluctuation", "Risk management rules only matter in losing streaks, not otherwise", "A winning streak always means risk must be increased"], "e": "Both winning and losing streaks are part of normal statistical fluctuation and don't justify overriding the rules."}]},
"247": {"t": "Case Study: Journal-Based Strategy Review", "s": "When the data tells you objectively what to change", "cards": [
  {"t": "The situation: 3 months of data", "b": "<p>Once a month Peti <strong style=\"color:#00FF9D\">goes through his trading journal</strong> — 3 months of data have accumulated, 90 trades in total.</p>"},
  {"t": "The discovery: a time-of-day pattern", "b": "<p>The data shows that <strong style=\"color:#00FF9D\">Peti's trades in the midday lull</strong> were 65% losing, while those in the first hour after the open were 68% profitable.</p>"},
  {"t": "The decision: based on data, not feeling", "b": "<p>Instead of continuing his daily routine \"by feel\", Peti decides <strong style=\"color:#00FF9D\">objectively, based on the data</strong>: he completely stops trading during the midday lull and concentrates on the hour after the open instead.</p>"},
  {"t": "The result: better expectancy", "b": "<p>The following month, by <strong style=\"color:#00FF9D\">dropping midday trading</strong>, Peti's overall expectancy improves significantly — not because he traded better, but because he skipped the statistically worse period.</p>"}],
 "qs": [
  {"q": "How regularly does Peti review his journal?", "o": ["He never reviews it, neglecting the opportunities the journal offers", "Only yearly, which would be too rare to recognise relevant patterns", "Once a month", "Several times a day, which would be too frequent for effective analysis"], "e": "Peti goes through his journal once a month, doing an objective, regular review."},
  {"q": "What does Peti discover in the data?", "o": ["That the broker's commission is too high, which would relate to another topic", "That trading is never worthwhile, giving up his strategy completely", "That he performs equally in every period, regardless of time of day", "That he loses 65% of the time in the midday lull and wins 68% in the hour after the open"], "e": "Peti discovers his performance is losing in the midday lull and profitable in the hour after the open."},
  {"q": "What decision does Peti make based on the discovery?", "o": ["He doubles the stake size of his midday trades, contradicting the data", "He immediately stops trading completely, reacting with a drastic decision", "He objectively stops midday trading, concentrating on the hour after the open", "He changes nothing, continuing the old routine despite the data"], "e": "Based on the data, Peti stops midday trading and concentrates on the statistically better period."},
  {"q": "Why does Peti's expectancy improve the following month?", "o": ["Because he traded better on every single trade, improving individual decisions", "Because he skipped the statistically worse period", "Because he increased his leverage", "Because he changed broker, which would relate more to another topic"], "e": "Peti's expectancy improves because he skipped the period with statistically worse performance."},
  {"q": "What is the lesson of the journal-based strategy review case?", "o": ["A regular, objective journal review can reveal concrete improvement opportunities", "It is always worth trading equally actively in every period, without exception", "Keeping a journal is a needless waste of time, with no practical benefit", "Decisions based on feeling are always better than data-based analysis"], "e": "A regular, objective journal review can reveal concrete, data-based improvement opportunities."}]},
"255": {"t": "The Availability Heuristic in Trading", "s": "When easily recalled examples get exaggerated weight", "cards": [
  {"t": "What is the availability heuristic?", "b": "<p>The <strong style=\"color:#00FF9D\">availability heuristic</strong> means that <strong style=\"color:#00FF9D\">easily recalled, vivid examples</strong> get disproportionately large weight in decision-making, regardless of their real statistical frequency.</p>"},
  {"t": "How does it appear in day trading?", "b": "<p>If you have recently heard a <strong style=\"color:#00FF9D\">dramatic success story</strong>, you may tend to overestimate the real probability of a similar strategy succeeding.</p>"},
  {"t": "How is this different from base rate neglect?", "b": "<p>Base rate neglect is about ignoring the <strong style=\"color:#00FF9D\">statistical base data</strong> — the availability heuristic focuses precisely on <strong style=\"color:#00FF9D\">why the estimate gets distorted</strong>: because of how easily something comes to mind.</p>"},
  {"t": "How can you protect yourself against it?", "b": "<p>It helps to consciously ask: <strong style=\"color:#00FF9D\">'Does this only seem common because it comes to mind easily?'</strong> — and to rely on systematic data instead.</p>"}],
 "qs": [
  {"q": "What is the availability heuristic?", "o": ["Overweighting old, forgotten examples in decision-making", "The broker's exact daily commission expressed in forints", "Disproportionately weighting easily recalled, vivid examples", "Precisely taking statistical base frequencies into account"], "e": "The availability heuristic means giving disproportionately large weight to easily recalled, vivid examples."},
  {"q": "How does it appear after hearing a dramatic success story?", "o": ["Our impression always precisely reflects the real statistical proportion", "It never influences our decision-making, it stays completely neutral", "We evaluate a similar strategy objectively, based on statistical data", "We may overestimate the real probability of a similar strategy succeeding"], "e": "After hearing a dramatic success story we may tend to overestimate the probability of a similar strategy succeeding."},
  {"q": "How is the availability heuristic different from base rate neglect?", "o": ["Base rate neglect never relates to the question of recall", "The availability heuristic is overweighting statistics", "The availability heuristic is only a theoretical concept, it doesn't occur in practice", "The availability heuristic focuses on why the estimate is distorted: because of ease of recall"], "e": "The availability heuristic focuses specifically on why ease of recall distorts the estimate."},
  {"q": "Which question helps recognise the availability heuristic?", "o": ["'Does this only seem common because it comes to mind easily?'", "'When exactly did this event happen in the market?'", "'How exciting is this particular story to me?'", "'Which person was it who passed this tale on to me?'"], "e": "It helps to ask whether something only seems common because it comes to mind easily."},
  {"q": "What is worth relying on to counterbalance the availability heuristic?", "o": ["Only your own gut feeling, with no data analysis at all", "The most recent, most vivid memories, which are precisely the source of the bias", "Exclusively other people's exciting, emotional accounts instead of other sources", "Systematic, long-term data instead of mere impression"], "e": "To counterbalance the availability heuristic it is worth relying on systematic, long-term data."}]}
});

